var e=`https://learn.microsoft.com/en-us/`,t={overview:`${e}fabric/fundamentals/microsoft-fabric-overview`,terms:`${e}fabric/fundamentals/fabric-terminology`,onelake:`${e}fabric/onelake/onelake-overview`,licenses:`${e}fabric/enterprise/licenses`,decisionStore:`${e}fabric/fundamentals/decision-guide-data-store`,decisionLhWh:`${e}fabric/fundamentals/decision-guide-lakehouse-warehouse`,lakehouse:`${e}fabric/data-engineering/lakehouse-overview`,warehouse:`${e}fabric/data-warehouse/data-warehousing`,eventhouse:`${e}fabric/real-time-intelligence/eventhouse`,medallion:`${e}fabric/onelake/onelake-medallion-lakehouse-architecture`,connectors:`${e}fabric/data-factory/connector-overview`,connections:`${e}fabric/data-factory/data-source-management`,dataFactory:`${e}fabric/data-factory/data-factory-overview`,gateway:`${e}fabric/data-factory/how-to-access-on-premises-data`,movement:`${e}fabric/data-factory/decision-guide-data-movement`,loadLakehouse:`${e}fabric/data-engineering/load-data-lakehouse`,notebookLoad:`${e}fabric/data-engineering/lakehouse-notebook-load-data`,shortcuts:`${e}fabric/onelake/onelake-shortcuts`,mirroring:`${e}fabric/mirroring/overview`,ingestWarehouse:`${e}fabric/data-warehouse/ingest-data`,copyInto:`${e}fabric/data-warehouse/ingest-data-copy`,dataflowGen2:`${e}fabric/data-factory/dataflows-gen2-overview`,catalog:`${e}fabric/governance/onelake-catalog-overview`,catalogExplore:`${e}fabric/governance/onelake-catalog-explore`,rtHub:`${e}fabric/real-time-hub/real-time-hub-overview`,eventhouseOneLake:`${e}fabric/real-time-intelligence/event-house-onelake-availability`,modelOneLake:`${e}fabric/enterprise/powerbi/onelake-integration-overview`,dimOverview:`${e}fabric/data-warehouse/dimensional-modeling-overview`,dimTables:`${e}fabric/data-warehouse/dimensional-modeling-dimension-tables`,factTables:`${e}fabric/data-warehouse/dimensional-modeling-fact-tables`,loadTables:`${e}fabric/data-warehouse/dimensional-modeling-load-tables`,tsqlSurface:`${e}fabric/data-warehouse/tsql-surface-area`,dataTypes:`${e}fabric/data-warehouse/data-types`,endpoint:`${e}fabric/data-engineering/lakehouse-sql-analytics-endpoint`,lakehousePrep:`${e}fabric/data-engineering/tutorial-lakehouse-data-preparation`,dataWrangler:`${e}fabric/data-science/data-wrangler`,qualify:`${e}sql/t-sql/queries/select-qualify-clause-transact-sql?view=fabric`,tryCast:`${e}sql/t-sql/functions/try-cast-transact-sql?view=fabric`,coalesce:`${e}sql/t-sql/language-elements/coalesce-transact-sql?view=fabric`,createView:`${e}sql/t-sql/statements/create-view-transact-sql?view=fabric`,createProc:`${e}sql/t-sql/statements/create-procedure-transact-sql?view=fabric`,merge:`${e}sql/t-sql/statements/merge-transact-sql?view=fabric`,concat:`${e}sql/t-sql/functions/concat-transact-sql?view=fabric`,groupBy:`${e}sql/t-sql/queries/select-group-by-transact-sql?view=fabric`,createFunction:`${e}sql/t-sql/statements/create-function-sql-data-warehouse?view=fabric`,scalarUdf:`${e}fabric/data-warehouse/how-to-inline-udf`,kqlQueryset:`${e}fabric/real-time-intelligence/kusto-query-set`,copyJob:`${e}fabric/data-factory/what-is-copy-job`,dbShortcut:`${e}fabric/real-time-intelligence/database-shortcut`,overClause:`${e}sql/t-sql/queries/select-over-clause-transact-sql?view=fabric`,nullif:`${e}sql/t-sql/language-elements/nullif-transact-sql?view=fabric`,castConvert:`${e}sql/t-sql/functions/cast-and-convert-transact-sql?view=fabric`,formatFn:`${e}sql/t-sql/functions/format-transact-sql?view=fabric`,whereClause:`${e}sql/t-sql/queries/where-transact-sql?view=fabric`,exceptIntersect:`${e}sql/t-sql/language-elements/set-operators-except-and-intersect-transact-sql?view=fabric`,unionOp:`${e}sql/t-sql/language-elements/set-operators-union-transact-sql?view=fabric`,kqlSortOp:`${e}kusto/query/sort-operator?view=microsoft-fabric`,cte:`${e}sql/t-sql/queries/with-common-table-expression-transact-sql?view=fabric`,notebookCombine:`${e}training/modules/fabric-transform-data-notebooks/4-combine-aggregate`,notebookClean:`${e}training/modules/fabric-transform-data-notebooks/3-shape-clean-data`,execute:`${e}sql/t-sql/language-elements/execute-transact-sql?view=fabric`,visualQuery:`${e}fabric/data-warehouse/visual-query-editor`,queryWarehouse:`${e}fabric/data-warehouse/query-warehouse`,kqlOperators:`${e}kusto/query/tutorials/learn-common-operators?view=microsoft-fabric`,kqlSummarize:`${e}kusto/query/summarize-operator?view=microsoft-fabric`,kqlJoin:`${e}kusto/query/join-operator?view=microsoft-fabric`,kqlJoinTutorial:`${e}kusto/query/tutorials/join-data-from-multiple-tables?view=microsoft-fabric`,kqlTake:`${e}kusto/query/take-operator?view=microsoft-fabric`,kqlTop:`${e}kusto/query/top-operator?view=microsoft-fabric`,kqlSort:`${e}kusto/query/sort-operator?view=microsoft-fabric`,kqlWhere:`${e}kusto/query/where-operator?view=microsoft-fabric`,kqlProject:`${e}kusto/query/project-operator?view=microsoft-fabric`,kqlExtend:`${e}kusto/query/extend-operator?view=microsoft-fabric`,kqlBin:`${e}kusto/query/bin-function?view=microsoft-fabric`,kqlDcount:`${e}kusto/query/dcount-aggregation-function?view=microsoft-fabric`,sqlToKql:`${e}kusto/query/sql-cheat-sheet?view=microsoft-fabric`,daxQueries:`${e}dax/dax-queries`,daxQueryView:`${e}power-bi/transform-model/dax-query-view`,summarizeColumns:`${e}dax/summarizecolumns-function-dax`,modes:`${e}power-bi/connect-data/service-dataset-modes-understand`,storageMode:`${e}power-bi/transform-model/desktop-storage-mode`,directLake:`${e}fabric/fundamentals/direct-lake-overview`,dlHow:`${e}fabric/fundamentals/direct-lake-how-it-works`,dlAnalyze:`${e}fabric/fundamentals/direct-lake-analyze-query-processing`,dlManage:`${e}fabric/fundamentals/direct-lake-security-integration`,composite:`${e}power-bi/transform-model/desktop-composite-models`,star:`${e}power-bi/guidance/star-schema`,manyToMany:`${e}power-bi/guidance/relationships-many-to-many`,relationships:`${e}power-bi/transform-model/desktop-relationships-understand`,calcGroups:`${e}power-bi/transform-model/calculation-groups`,dynamicFormat:`${e}power-bi/create-reports/desktop-dynamic-format-strings`,fieldParams:`${e}power-bi/create-reports/power-bi-field-parameters`,largeModels:`${e}fabric/enterprise/powerbi/service-premium-large-models`,varRef:`${e}dax/var-dax`,varBP:`${e}dax/best-practices/dax-variables`,window:`${e}dax/window-function-dax`,offset:`${e}dax/offset-function-dax`,index:`${e}dax/index-function-dax`,infoFuncs:`${e}dax/information-functions-dax`,filterFuncs:`${e}dax/filter-functions-dax`,sumx:`${e}dax/sumx-function-dax`,calculate:`${e}dax/calculate-function-dax`,isinscope:`${e}dax/isinscope-function-dax`,hasonevalue:`${e}dax/hasonevalue-function-dax`,selectedvalue:`${e}dax/selectedvalue-function-dax`,perfAnalyzer:`${e}power-bi/create-reports/performance-analyzer`,optimization:`${e}power-bi/guidance/power-bi-optimization`,dataReduction:`${e}power-bi/guidance/import-modeling-data-reduction`,bpFilter:`${e}dax/best-practices/dax-avoid-avoid-filter-as-filter-argument`,bpDivide:`${e}dax/best-practices/dax-divide-function-operator`,bpCountrows:`${e}dax/best-practices/dax-countrows`,incremental:`${e}power-bi/connect-data/incremental-refresh-overview`,incrementalCfg:`${e}power-bi/connect-data/incremental-refresh-configure`,semanticModels:`${e}fabric/data-warehouse/semantic-models`,aggregations:`${e}power-bi/transform-model/aggregations-advanced`,roles:`${e}fabric/fundamentals/roles-workspaces`,permissionModel:`${e}fabric/security/permission-model`,shareItems:`${e}fabric/fundamentals/share-items`,workspaces:`${e}fabric/fundamentals/workspaces`,whRls:`${e}fabric/data-warehouse/row-level-security`,whCls:`${e}fabric/data-warehouse/column-level-security`,whGranular:`${e}fabric/data-warehouse/sql-granular-permissions`,whDdm:`${e}fabric/data-warehouse/dynamic-data-masking`,onelakeSecurity:`${e}fabric/onelake/security/get-started-security`,onelakeAccessModel:`${e}fabric/onelake/security/data-access-control-model`,modelRls:`${e}fabric/security/service-admin-row-level-security`,modelOls:`${e}fabric/security/service-admin-object-level-security`,infoProtection:`${e}fabric/governance/information-protection`,endorsement:`${e}fabric/governance/endorsement-overview`,gitIntro:`${e}fabric/cicd/git-integration/intro-to-git-integration`,gitProcess:`${e}fabric/cicd/git-integration/git-integration-process`,pbip:`${e}power-bi/developer/projects/projects-overview`,giveAccess:`${e}fabric/fundamentals/give-access-workspaces`,createSecurityPolicy:`${e}sql/t-sql/statements/create-security-policy-transact-sql?view=fabric`,pipelinesIntro:`${e}fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines`,pipelinesStart:`${e}fabric/cicd/deployment-pipelines/get-started-with-deployment-pipelines`,pipelinesProcess:`${e}fabric/cicd/deployment-pipelines/understand-the-deployment-process`,pipelinesRules:`${e}fabric/cicd/deployment-pipelines/create-rules`,impact:`${e}fabric/governance/impact-analysis`,lineage:`${e}fabric/governance/lineage`,xmla:`${e}fabric/enterprise/powerbi/service-premium-connect-tools`,tmslRefresh:`${e}analysis-services/tmsl/refresh-command-tmsl?view=sql-analysis-services-2025`,templates:`${e}power-bi/create-reports/desktop-templates`,pbids:`${e}power-bi/connect-data/desktop-data-sources`,sharedModels:`${e}power-bi/connect-data/service-datasets-across-workspaces`},n=`carding-machine`,r=`recipe-book`,i=[{id:`CM-V1`,machineId:n,bulletIds:[`P2.7`],format:`single`,difficulty:2,stem:`A notebook loads raw_sales into a Spark DataFrame. A source system retried some writes, so several rows share an order_id but have different load timestamps. You must keep exactly one row per order_id. Which PySpark call should you use?`,sources:[t.notebookClean],options:[{id:`a`,text:`df.dropDuplicates()`,explain:`With no column list, dropDuplicates() removes only rows that are identical in every column. These rows differ in their load timestamp, so they all stay.`},{id:`b`,text:`df.dropna(subset=["order_id"])`,explain:`dropna drops rows where order_id is null. It doesn’t remove repeated order_id values.`},{id:`c`,text:`df.dropDuplicates(["order_id"])`,explain:`Correct. Passing the business key de-duplicates on that column, keeping one row per order_id.`},{id:`d`,text:`df.fillna({"order_id": 0})`,explain:`fillna replaces nulls with a default value. It doesn’t remove any rows.`}],answer:`c`},{id:`CM-V2`,machineId:n,bulletIds:[`P2.7`],format:`multi`,difficulty:2,stem:`After de-duplicating a sales DataFrame in a notebook, you find nulls in two places. A missing region should appear as "Unknown" and a missing discount should count as 0, so totals don’t turn null. Rows with no customer_id can’t be joined to customer data and must be removed. Which two PySpark calls meet these requirements? Choose two.`,sources:[t.notebookClean],options:[{id:`a`,text:`df.fillna({"region": "Unknown", "discount": 0})`,explain:`Correct. fillna with a dictionary replaces nulls column by column with the value you give each one.`},{id:`b`,text:`df.dropDuplicates(["customer_id"])`,explain:`This keeps one row per customer_id value, so it would drop valid sales. Removing rows with a missing key is what dropna does.`},{id:`c`,text:`df.fillna({"customer_id": "Unknown"})`,explain:`This keeps the rows that must be removed, now with a key that matches no customer.`},{id:`d`,text:`df.dropna(subset=["customer_id"])`,explain:`Correct. dropna with a subset removes only rows where customer_id is null.`}],answers:[`a`,`d`]},{id:`CM-V3`,machineId:n,bulletIds:[`P2.7`],format:`yesno`,difficulty:2,stem:`A data engineer is cleaning a lakehouse table with PySpark in a Fabric notebook. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.notebookClean],statements:[{id:`s1`,text:`df.dropDuplicates() with no arguments removes only rows that match in every column.`,answer:!0,explain:`Yes. Without a column list it removes exact duplicate rows; pass a column list to de-duplicate on a business key.`},{id:`s2`,text:`df.dropDuplicates(["order_id"]) keeps every row whose order_id appears more than once.`,answer:!1,explain:`No. It keeps one row per order_id.`},{id:`s3`,text:`Leaving a null in a numeric column can make calculations that use it return null.`,answer:!0,explain:`Yes. A null in a numeric column produces null results for calculations that involve it, which is why you fill or drop nulls explicitly.`},{id:`s4`,text:`df.fillna(...) removes the rows that contain null values.`,answer:!1,explain:`No. fillna replaces nulls with defaults. dropna is the call that removes rows.`}]},{id:`RB-V1`,machineId:r,bulletIds:[`P2.1`],format:`single`,difficulty:3,preview:!0,stem:`In a Fabric warehouse, a developer creates a scalar user-defined function (preview) with WITH INLINE = AUTO. The function reads a customer’s start date from dbo.Customer and returns DATEDIFF(DAY, @MemberSince, GETUTCDATE()). Calling it to set a variable works, but using it in SELECT … FROM dbo.Customer fails. What should the developer change?`,sources:[t.scalarUdf,t.createFunction],options:[{id:`a`,text:`Replace GETUTCDATE() with SYSUTCDATETIME() inside the function`,explain:`Learn’s own example of a non-inlineable function uses SYSUTCDATETIME(), a nondeterministic system function, so the function still isn’t inlineable.`},{id:`b`,text:`Pass the current date and time into the function as a parameter instead of calling GETUTCDATE() in its body`,explain:`Correct. A time-dependent built-in function in the body makes the UDF non-inlineable, and a non-inlineable scalar UDF can’t be used in a SELECT … FROM query on a user table. Learn’s fix is to pass the value in as a parameter.`},{id:`c`,text:`Split the logic into several IF branches, each with its own RETURN statement`,explain:`Multiple RETURN statements make a data-access UDF non-inlineable, so this makes things worse.`},{id:`d`,text:`Wrap the calculation in a WHILE loop that runs once`,explain:`A WHILE loop in the body also prevents scalar UDF inlining.`}],answer:`b`},{id:`RB-V2`,machineId:r,bulletIds:[`P2.1`],format:`yesno`,difficulty:2,preview:!0,stem:`A team is deciding whether to use scalar user-defined functions in Fabric Data Warehouse. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.createFunction,t.scalarUdf],statements:[{id:`s1`,text:`Scalar UDFs are currently a preview feature in Fabric Data Warehouse.`,answer:!0,explain:`Yes. Learn labels scalar UDFs (and external UDFs) as preview features in Fabric Data Warehouse.`},{id:`s2`,text:`A scalar UDF that isn’t inlineable can be used in a SELECT … FROM query on a user table.`,answer:!1,explain:`No. A non-inlineable scalar UDF can’t be part of a SELECT … FROM query on a user table, though it can run as a standalone call.`},{id:`s3`,text:`The is_inlineable column of sys.sql_modules shows whether a scalar UDF can be inlined.`,answer:!0,explain:`Yes. is_inlineable is 1 when the definition is inlineable and 0 when it isn’t.`},{id:`s4`,text:`A scalar UDF whose body calls GETDATE() can be inlined.`,answer:!1,explain:`No. A time-dependent built-in function such as GETDATE() prevents both inlining techniques.`}]}],a=[{id:`BC-01`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:1,trapPairId:`catalog-vs-rthub`,stem:`You need to find all certified lakehouses and semantic models in the Finance domain that you have access to, and review each item’s owner, schema, and lineage. Where should you start?`,sources:[t.catalogExplore,t.onelake],options:[{id:`a`,text:`The Real-Time hub`,explain:`The Real-Time hub lists streams and KQL tables for data in motion, not lakehouses and semantic models with endorsement filters.`},{id:`b`,text:`The Explore tab of the OneLake catalog`,explain:`Correct. Explore lists items you can access, filters by domain, item type, and endorsement, and shows details such as owner, schema, and lineage.`},{id:`c`,text:`The workspace lineage view`,explain:`Lineage view shows one workspace’s items and connections; it doesn’t search across domains by endorsement.`},{id:`d`,text:`The Monitoring hub`,explain:`Monitoring tracks activities and runs; it isn’t a discovery catalog for data items.`}],answer:`b`},{id:`BC-02`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:2,trapPairId:`catalog-vs-rthub`,stem:`Your organization streams change data capture (CDC) events from an Azure SQL Database and telemetry from Azure IoT Hub. You need a single tenant-wide place to discover these streams and ingest them into Fabric. What should you use?`,sources:[t.rtHub],options:[{id:`a`,text:`The OneLake catalog`,explain:`The OneLake catalog discovers and governs items such as lakehouses and semantic models, not data in motion.`},{id:`b`,text:`A mirrored database`,explain:`Mirroring replicates a database into OneLake; it isn’t a hub for discovering streams such as IoT Hub telemetry.`},{id:`c`,text:`The Real-Time hub`,explain:`Correct. The Real-Time hub is the tenant-wide place for streaming data, with connectors for Azure SQL Database CDC and Azure IoT Hub.`},{id:`d`,text:`A KQL queryset`,explain:`A KQL queryset runs queries against a KQL database; it doesn’t discover or connect stream sources.`}],answer:`c`},{id:`BC-03`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`match`,difficulty:2,stem:`The OneLake catalog has three tabs. Match each task to the tab you should use.`,sources:[t.catalog],prompts:[{id:`p1`,text:`Browse and filter Fabric items, then open an item’s details without losing the list`},{id:`p2`,text:`See governance insights and recommended actions for the data you own`},{id:`p3`,text:`Review workspace roles and OneLake security roles across items in one view`}],choices:[{id:`c1`,text:`Explore`},{id:`c2`,text:`Govern`},{id:`c3`,text:`Secure`},{id:`c4`,text:`Monitor`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Explore has the items list with an in-context item details view, plus filters and selectors.`},{promptId:`p2`,choiceId:`c2`,explain:`Govern shows governance insights and recommended actions for data you own.`},{promptId:`p3`,choiceId:`c3`,explain:`Secure gives a unified view of workspace roles and OneLake security roles. "Monitor" isn’t one of the catalog’s three tabs.`}]},{id:`BC-04`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`yesno`,difficulty:2,stem:`You are introducing the OneLake catalog to report authors. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.catalog,t.catalogExplore],statements:[{id:`s1`,text:`The OneLake catalog is also available inside Microsoft Teams and Microsoft Excel.`,answer:!0,explain:`Yes. Learn says the catalog is embedded in Teams, Excel, and Copilot Studio.`},{id:`s2`,text:`Finding an item in the OneLake catalog automatically grants you read access to its data.`,answer:!1,explain:`No. Explore lists items you already have access to or can request access to; it doesn’t grant access.`},{id:`s3`,text:`You can discover catalog metadata programmatically with a REST API.`,answer:!0,explain:`Yes. Learn mentions the Microsoft Fabric Catalog Search REST API.`}]},{id:`BC-05`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:2,stem:`You found an IoT stream in the Real-Time hub. You need to run KQL queries over the stream’s data. According to Learn, what should you do?`,sources:[t.rtHub],options:[{id:`a`,text:`Open the stream’s eventstream, add a KQL database destination, then query the KQL table`,explain:`Correct. To analyze a stream, Learn says to add a KQL Database destination to the eventstream and run queries against the KQL table.`},{id:`b`,text:`Create a OneLake shortcut to the stream in a lakehouse`,explain:`Shortcuts point to stored data in OneLake or external storage, not to a live stream.`},{id:`c`,text:`Connect a Dataflow Gen2 to the stream, load it into a warehouse table, and query it with T-SQL`,explain:`This isn’t the path Learn describes for analyzing a Real-Time hub stream with KQL.`},{id:`d`,text:`Enable OneLake availability on the stream`,explain:`OneLake availability is set on KQL databases or tables, not on the stream itself.`}],answer:`a`},{id:`BC-06`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`multi`,difficulty:2,stem:`You plan event-driven automation in Fabric. Which two kinds of events does the Real-Time hub list so you can react to them? Choose two.`,sources:[t.rtHub],options:[{id:`a`,text:`Fabric workspace item events`,explain:`Correct. Fabric events include workspace item events, OneLake events, job events, and capacity overview events.`},{id:`b`,text:`Semantic model DAX query events`,explain:`DAX query events aren’t among the Fabric or Azure event sources listed in the Real-Time hub.`},{id:`c`,text:`Azure Blob Storage events`,explain:`Correct. Azure storage account events are listed under Azure events.`},{id:`d`,text:`Power BI report page view events`,explain:`Report page views aren’t listed as Real-Time hub event sources.`}],answers:[`a`,`c`]},{id:`BC-07`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:1,stem:`A new analyst opens the OneLake catalog for the first time. Which tab opens by default?`,sources:[t.catalog],options:[{id:`a`,text:`Govern`,explain:`Govern is for governance status and actions; it isn’t the default tab.`},{id:`b`,text:`Secure`,explain:`Secure is for reviewing roles; it isn’t the default tab.`},{id:`c`,text:`Home`,explain:`Home is the Fabric home page, not a OneLake catalog tab.`},{id:`d`,text:`Explore`,explain:`Correct. Learn: "By default, OneLake catalog opens on the Explore tab."`}],answer:`d`},{id:`BC-08`,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:2,stem:`You need to filter a stream from the Real-Time hub and group events before sending them to a destination. Where do you add these transformations?`,sources:[t.rtHub,t.kqlQueryset,t.copyJob],options:[{id:`a`,text:`In the KQL queryset attached to the stream`,explain:`A queryset queries data already in a KQL database; it doesn’t transform the stream in flight.`},{id:`b`,text:`In the parent eventstream’s editor`,explain:`Correct. Learn: open the parent eventstream and add transformations such as Filter, Aggregate, and Group by.`},{id:`c`,text:`In the OneLake catalog’s item details`,explain:`Item details show metadata; they don’t transform streams.`},{id:`d`,text:`In a Copy job`,explain:`Copy job moves batch data with incremental or CDC copy; it isn’t the stream processing editor.`}],answer:`b`},{id:`VS-01`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:1,trapPairId:`stores`,stem:`A data engineering team works in PySpark notebooks and stores JSON, images, and Parquet files alongside tables. Analysts only need to read curated tables with T-SQL. Which data store should the team create?`,sources:[t.decisionLhWh,t.decisionStore],options:[{id:`a`,text:`A lakehouse`,explain:`Correct. A lakehouse suits Spark developers and structured plus unstructured data, and its SQL analytics endpoint lets analysts read tables with T-SQL.`},{id:`b`,text:`A warehouse`,explain:`A warehouse is T-SQL-first for structured data; it isn’t the fit for Spark developers working with unstructured files.`},{id:`c`,text:`An eventhouse`,explain:`An eventhouse is for streaming, time-based event data queried with KQL.`},{id:`d`,text:`A SQL database in Fabric`,explain:`SQL database in Fabric targets operational OLTP workloads, not Spark-based data engineering over files.`}],answer:`a`},{id:`VS-02`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:2,trapPairId:`warehouse-vs-sql-database`,stem:`An application team needs a database for a new order-entry app with high concurrency, strongly enforced foreign keys, and automatic index tuning. The data must also be available for analytics in Fabric. Which Fabric data store should they use?`,sources:[t.decisionStore],options:[{id:`a`,text:`A warehouse`,explain:`A warehouse is for analytical workloads (enterprise warehousing, SQL-based BI), not an OLTP order-entry app.`},{id:`b`,text:`A lakehouse`,explain:`A lakehouse targets data engineering and big data, not high-concurrency transactional apps.`},{id:`c`,text:`An eventhouse`,explain:`An eventhouse is for streaming event analytics, not transactional order entry.`},{id:`d`,text:`A SQL database in Fabric`,explain:`Correct. Learn’s scenario picks SQL database in Fabric for operational OLTP needs like enforced foreign keys and automatic index tuning; its SQL analytics endpoint serves analytics.`}],answer:`d`},{id:`VS-03`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:2,trapPairId:`stores`,stem:`You need to store billions of rows of high-granularity telemetry and run interactive time-series and geospatial analysis within seconds, with fast queries from Power BI. Which data store does Learn recommend?`,sources:[t.decisionStore,t.eventhouse],options:[{id:`a`,text:`A lakehouse with Spark notebooks`,explain:`A lakehouse suits data engineering and ML; Learn recommends an eventhouse for high-granularity streaming event analytics.`},{id:`b`,text:`An eventhouse`,explain:`Correct. Learn recommends an eventhouse for streaming event data and high-granularity interactive analytics, including time series and geospatial functions.`},{id:`c`,text:`A warehouse`,explain:`A warehouse targets enterprise SQL-based BI over structured data, not streaming telemetry analytics.`},{id:`d`,text:`Cosmos DB in Fabric`,explain:`Cosmos DB in Fabric is for NoSQL application data, not telemetry analytics.`}],answer:`b`},{id:`VS-04`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`yesno`,difficulty:2,trapPairId:`stores`,stem:`You are comparing a lakehouse and a warehouse for a new project. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.decisionLhWh],statements:[{id:`s1`,text:`Both store their tables in Delta format in OneLake.`,answer:!0,explain:`Yes. Both store data in Delta Lake format in OneLake and share the same SQL engine.`},{id:`s2`,text:`Only the warehouse supports multi-table transactions.`,answer:!0,explain:`Yes. The decision guide maps "need multi-table transactions" to the warehouse.`},{id:`s3`,text:`The lakehouse’s SQL analytics endpoint can run INSERT and UPDATE statements against its Delta tables.`,answer:!1,explain:`No. The SQL analytics endpoint is read-only for data; it only reads Delta tables.`}]},{id:`VS-05`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:2,stem:`A team of experienced SQL Server developers is moving to Fabric. They want to reuse their existing T-SQL code, use SQL Server Management Studio, and query lakehouse Delta tables from the same queries. Which data store should they choose?`,sources:[t.decisionStore,t.mirroring],options:[{id:`a`,text:`A lakehouse with Spark SQL notebooks`,explain:`Spark SQL isn’t T-SQL, and the team wants to reuse T-SQL and SSMS.`},{id:`b`,text:`An eventhouse with KQL querysets`,explain:`KQL is a different language; this doesn’t reuse the team’s T-SQL code.`},{id:`c`,text:`A warehouse`,explain:`Correct. Learn’s scenario: a warehouse lets SQL developers reuse T-SQL and SSMS, and query lakehouse Delta tables with three-part names.`},{id:`d`,text:`A mirrored database`,explain:`A mirrored database replicates an external database read-only; it isn’t where the team develops new T-SQL logic.`}],answer:`c`},{id:`VS-06`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`match`,difficulty:2,trapPairId:`stores`,stem:`Match each developer persona to the primary language Learn associates with the Fabric data store they’re most likely to use.`,sources:[t.decisionStore],prompts:[{id:`p1`,text:`Data engineer building a lakehouse`},{id:`p2`,text:`Data warehouse developer building a warehouse`},{id:`p3`,text:`App developer analyzing events in an eventhouse`}],choices:[{id:`c1`,text:`Spark (PySpark, Scala, Spark SQL, R)`},{id:`c2`,text:`T-SQL`},{id:`c3`,text:`KQL`},{id:`c4`,text:`DAX`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Lakehouses are developed primarily with Spark languages.`},{promptId:`p2`,choiceId:`c2`,explain:`Warehouses are developed primarily with T-SQL.`},{promptId:`p3`,choiceId:`c3`,explain:`Eventhouses are queried primarily with KQL. DAX (unused) is the semantic model language, not a data store language.`}]},{id:`VS-07`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:3,stem:`A team stores several terabytes in Fabric. Most of the people running T-SQL only read data and never write INSERT, UPDATE, or DELETE statements. The developers who load data work in notebooks. Which data store does Learn’s decision guide pick in this scenario?`,sources:[t.decisionStore],options:[{id:`a`,text:`A warehouse, because the team uses T-SQL`,explain:`The T-SQL users only consume data, so they don’t need warehouse write capabilities.`},{id:`b`,text:`An eventhouse, because the data volume is large and grows quickly every day`,explain:`Volume alone doesn’t point to an eventhouse; that’s for streaming event data.`},{id:`c`,text:`A SQL database in Fabric, because it supports T-SQL`,explain:`SQL database in Fabric is for OLTP workloads, not a notebook-loaded analytics store.`},{id:`d`,text:`A lakehouse, using its SQL analytics endpoint for the T-SQL readers`,explain:`Correct. Learn’s scenario chooses a lakehouse: engineers use notebooks and T-SQL consumers read through the SQL analytics endpoint.`}],answer:`d`},{id:`VS-08`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`multi`,difficulty:2,stem:`You are deciding between a lakehouse and a warehouse. Which two requirements point to a warehouse? Choose two.`,sources:[t.decisionLhWh],options:[{id:`a`,text:`The data includes unstructured files such as images`,explain:`Unstructured or mixed data maps to the lakehouse.`},{id:`b`,text:`The team develops with T-SQL`,explain:`Correct. T-SQL development maps to the warehouse in the decision guide.`},{id:`c`,text:`The team develops with PySpark`,explain:`Spark development maps to the lakehouse.`},{id:`d`,text:`Loads must update several tables in one transaction`,explain:`Correct. Multi-table transactions map to the warehouse.`}],answers:[`b`,`d`]},{id:`VS-09`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:2,stem:`You need to store a product catalog as JSON documents for a web app, using a NoSQL API, while keeping the data available in OneLake. Which Fabric data store fits?`,sources:[t.decisionStore,t.dbShortcut],options:[{id:`a`,text:`A warehouse`,explain:`A warehouse is a relational T-SQL store for analytics, not a NoSQL document database.`},{id:`b`,text:`Cosmos DB in Fabric`,explain:`Correct. Learn recommends Cosmos DB in Fabric for NoSQL databases; its data is available in OneLake.`},{id:`c`,text:`An eventhouse`,explain:`Eventhouses handle semistructured event data for analytics, not a NoSQL application database.`},{id:`d`,text:`A KQL database shortcut`,explain:`A database shortcut shares an existing KQL database; it isn’t an application data store.`}],answer:`b`},{id:`VS-10`,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:3,trapPairId:`stores`,stem:`All Fabric data stores make their data available in OneLake in open table format by default, except one, where it is an opt-in setting. Which one?`,sources:[t.decisionStore],options:[{id:`a`,text:`A KQL database in an eventhouse`,explain:`Correct. Learn: for a KQL database in an eventhouse, OneLake availability is an opt-in feature.`},{id:`b`,text:`A warehouse`,explain:`Warehouse data is stored as Delta in OneLake by default.`},{id:`c`,text:`A lakehouse`,explain:`Lakehouse tables are Delta in OneLake by default.`},{id:`d`,text:`A SQL database in Fabric`,explain:`Learn lists SQL database in Fabric as available in OneLake by default.`}],answer:`a`},{id:`SS-01`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:2,trapPairId:`onelake-availability-vs-integration`,stem:`Telemetry lands in a KQL database in an eventhouse. Data engineers want to read the same data from a lakehouse through a shortcut, in Delta format, without building a copy pipeline. What should you do first?`,sources:[t.eventhouseOneLake],options:[{id:`a`,text:`Turn on OneLake integration in the semantic model settings`,explain:`That setting exports semantic model import tables, not KQL database data.`},{id:`b`,text:`Create a mirrored database from the eventhouse`,explain:`Mirroring replicates external operational databases; it isn’t how KQL data is exposed as Delta.`},{id:`c`,text:`Turn on OneLake availability for the KQL database or table`,explain:`Correct. OneLake availability exposes KQL data as Delta in OneLake, which a lakehouse can reach through a shortcut.`},{id:`d`,text:`Add a Copy job from the eventhouse to the lakehouse`,explain:`A Copy job makes a physical copy, which the requirement wants to avoid.`}],answer:`c`},{id:`SS-02`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`yesno`,difficulty:3,stem:`OneLake availability is turned on for a KQL database. For each task, select Yes if you can do it without first turning OneLake availability off. Otherwise, select No.`,sources:[t.eventhouseOneLake],statements:[{id:`s1`,text:`Add a new column to a table.`,answer:!0,explain:`Yes. Adding or deleting a column is supported while OneLake availability is on.`},{id:`s2`,text:`Rename a table.`,answer:!1,explain:`No. Renaming tables isn’t allowed while OneLake availability is on.`},{id:`s3`,text:`Apply row-level security to a table.`,answer:!1,explain:`No. Applying RLS to tables isn’t allowed while OneLake availability is on.`}]},{id:`SS-03`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:2,trapPairId:`onelake-availability-vs-integration`,stem:`You turned on OneLake integration for an import-mode semantic model. A data scientist reports that no Delta tables appear in the model’s OneLake folder. What should you do?`,sources:[t.modelOneLake],options:[{id:`a`,text:`Switch the model’s tables to Direct Lake`,explain:`OneLake integration applies to import tables; switching modes doesn’t trigger the export.`},{id:`b`,text:`Run a manual or scheduled refresh of the semantic model`,explain:`Correct. Import data is written to Delta tables in OneLake only when at least one manual or scheduled refresh runs.`},{id:`c`,text:`Enable large semantic model storage format`,explain:`Learn ties the export to a manual or scheduled refresh; the storage format setting doesn’t trigger it.`},{id:`d`,text:`Turn on OneLake availability for the workspace`,explain:`OneLake availability is an eventhouse setting; it doesn’t trigger a semantic model export.`}],answer:`b`},{id:`SS-04`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:2,stem:`You want to turn on OneLake integration for an import semantic model so its tables are written to Delta in OneLake. On which kind of workspace is this supported?`,sources:[t.modelOneLake],options:[{id:`a`,text:`A Power BI Pro workspace`,explain:`OneLake integration isn’t supported on Power BI Pro.`},{id:`b`,text:`A Premium Per User (PPU) workspace`,explain:`OneLake integration isn’t supported on Premium Per User.`},{id:`c`,text:`A Power BI Embedded A SKU workspace`,explain:`OneLake integration isn’t supported on Embedded A/EM SKUs.`},{id:`d`,text:`A workspace on a Fabric F SKU capacity`,explain:`Correct. OneLake integration for semantic models is supported on Premium P and Fabric F SKUs only.`}],answer:`d`},{id:`SS-05`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`order`,difficulty:2,stem:`You need lakehouse users to query the tables of an import semantic model through a shortcut. Put the steps in order.`,sources:[t.modelOneLake],items:[{id:`i1`,text:`In Lakehouse explorer, create a Microsoft OneLake shortcut under Tables and select the semantic model’s tables`,explain:`Last: the shortcut points to the exported Delta tables.`},{id:`i2`,text:`Turn on OneLake integration in the semantic model settings`,explain:`First: the model must be configured to export import tables.`},{id:`i3`,text:`Run a manual or scheduled refresh of the semantic model`,explain:`Second: data is written to Delta only during a refresh.`}],answerOrder:[`i2`,`i3`,`i1`]},{id:`SS-06`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:3,stem:`You just turned on OneLake availability for a busy KQL table that receives a trickle of small events. Analysts query the Delta copy a few minutes later and see fewer rows than the KQL table. Why?`,sources:[t.eventhouseOneLake],options:[{id:`a`,text:`The eventhouse batches writes to OneLake and can delay them until it has enough data for well-sized Parquet files`,explain:`Correct. The adaptive behavior can delay writes (by default up to 3 hours) to avoid many small files.`},{id:`b`,text:`The table’s retention policy removed the rows from OneLake only`,explain:`The retention policy applies to both the KQL table and OneLake, so it doesn’t explain a gap between them.`},{id:`c`,text:`OneLake availability copies only the data that was ingested before it was turned on, so newer rows are skipped until the next rebuild`,explain:`It’s the opposite. Learn: turning on availability at the table level makes that table and its data available in OneLake.`},{id:`d`,text:`The SQL analytics endpoint caches results for 24 hours`,explain:`This isn’t the documented reason; the delay comes from the eventhouse’s write batching.`}],answer:`a`},{id:`SS-07`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:2,trapPairId:`onelake-availability-vs-integration`,stem:`You need to temporarily turn off OneLake availability on a KQL database to truncate a table. What happens to the data already in OneLake when you turn it off?`,sources:[t.eventhouseOneLake],options:[{id:`a`,text:`It stays in OneLake but stops updating`,explain:`Learn says turning it off soft deletes the data from OneLake; it doesn’t remain as a frozen copy.`},{id:`b`,text:`It is moved into the lakehouse that has a shortcut to it`,explain:`Data isn’t moved into lakehouses; shortcuts only point to it.`},{id:`c`,text:`It is soft deleted from OneLake`,explain:`Correct. Turning off OneLake availability soft deletes the data from OneLake; turning it back on makes it available again, including historic backfill.`},{id:`d`,text:`It is converted to Parquet files in the Files area`,explain:`This isn’t a documented behavior.`}],answer:`c`},{id:`SS-08`,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`multi`,difficulty:2,stem:`A KQL database has OneLake availability turned on. Which two Fabric engines or features can then read its data in Delta format? Choose two.`,sources:[t.eventhouseOneLake],options:[{id:`a`,text:`Power BI Direct Lake mode`,explain:`Correct. Learn lists Direct Lake mode in Power BI among the engines that can query the Delta data.`},{id:`b`,text:`Power BI Desktop live connection to Analysis Services`,explain:`A live connection to Analysis Services doesn’t read OneLake Delta tables.`},{id:`c`,text:`The XMLA endpoint`,explain:`The XMLA endpoint exposes semantic models, not KQL database data in OneLake.`},{id:`d`,text:`Spark notebooks`,explain:`Correct. Notebooks are listed among the engines that can query the data.`}],answers:[`a`,`d`]}],o=`thread-intake`,s=`bale-catalog`,c=`vat-selector`,l=`recipe-book`,u=`dye-vat`,d=`weave-planner`,f=`twisting-frame`,p=`carding-machine`,m=`inspection-bench`,h=[{id:`TI-H1`,machineId:o,bulletIds:[`P1.1`],format:`single`,difficulty:3,stem:`A Fabric administrator creates a cloud connection to an Azure SQL database under Settings > Manage connections and gateways, and a pipeline’s Copy activity uses it successfully. A data engineer then builds a Dataflow Gen2 against the same database and expects to pick that connection. What should the engineer do?`,sources:[t.connections],options:[{id:`a`,text:`Install an on-premises data gateway so the dataflow can reuse the cloud connection`,explain:`A gateway is for sources behind a firewall or on-premises. The database here is a cloud source, and a gateway doesn’t change which items can use a cloud connection.`},{id:`b`,text:`Create the dataflow’s connection through Power Query Online’s Get data experience`,explain:`Correct. Learn says cloud connections created under Manage connections and gateways currently work with pipelines and Kusto; for dataflows and semantic models, you create connections through Get data.`},{id:`c`,text:`Set a privacy level on the existing connection so dataflows can see it`,explain:`A privacy level controls how data from sources can be combined. It doesn’t make a connection available to other item types.`},{id:`d`,text:`Share the existing connection with the engineer; every connection works in every Fabric item`,explain:`Sharing gives the engineer permission to use the connection, but Learn limits these cloud connections to pipelines and Kusto for now.`}],answer:`b`},{id:`TI-H2`,machineId:o,bulletIds:[`P1.3`],format:`multi`,difficulty:3,trapPairId:`shortcut-mirror-copy`,stem:`A retailer has two requirements. Product reference files in Azure Data Lake Storage Gen2 must be queryable from a Fabric lakehouse without copying them, always reading the current files at the source. An operational Azure SQL database must be replicated continuously into OneLake as read-only Delta tables for reporting, without anyone building or scheduling a pipeline. Which two features should you use? Choose two.`,sources:[t.shortcuts,t.mirroring,t.movement],options:[{id:`a`,text:`A Copy job with incremental loads for the database`,explain:`A Copy job makes and maintains a physical copy that you configure and run. Learn recommends mirroring when you mainly need data replicated for reporting without building a pipeline.`},{id:`b`,text:`A OneLake shortcut to the ADLS Gen2 folder`,explain:`Correct. A shortcut behaves like a symbolic link: it references the data in place, with no copy.`},{id:`c`,text:`T-SQL COPY INTO from the ADLS Gen2 files into a warehouse`,explain:`COPY INTO loads a copy into a warehouse table, which breaks the "without copying" requirement.`},{id:`d`,text:`Mirroring for the Azure SQL database`,explain:`Correct. Mirroring continuously replicates the database into OneLake as Delta tables, which Learn’s movement guide calls read-only, with no pipeline to build.`}],answers:[`b`,`d`]},{id:`BC-H1`,machineId:s,bulletIds:[`P1.2`],format:`single`,difficulty:3,trapPairId:`catalog-vs-rthub`,stem:`A finance analyst must find certified lakehouses in the Finance domain and see who owns each one. On the same day, an IoT team must find out whether a stream fed by Kafka already exists before building a new one. Which approach meets both needs?`,sources:[t.catalogExplore,t.catalog,t.rtHub],options:[{id:`a`,text:`The OneLake catalog’s Govern tab for the analyst, and the Secure tab for the IoT team`,explain:`Govern shows governance insights for data you own, and Secure shows roles. Neither lists data streams.`},{id:`b`,text:`The Real-Time hub for both teams, filtered by domain and by source`,explain:`The Real-Time hub lists data streams, KQL tables, and events, not lakehouses with their endorsement.`},{id:`c`,text:`The OneLake catalog’s Explore tab, filtered by domain and endorsement, for the analyst; the Real-Time hub for the IoT team`,explain:`Correct. Explore filters items by domain, endorsement, and more, and shows owner details. The Real-Time hub is the tenant-wide place to find data streams and their sources.`},{id:`d`,text:`The OneLake catalog’s Explore tab for both teams, filtered by item type`,explain:`The catalog is for data items at rest. Streams and their sources are discovered in the Real-Time hub.`}],answer:`c`},{id:`BC-H2`,machineId:s,bulletIds:[`P1.2`],format:`yesno`,difficulty:3,stem:`A new analyst is learning how discovery works in Fabric. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.catalogExplore,t.catalog,t.rtHub],statements:[{id:`s1`,text:`Finding a lakehouse in the OneLake catalog’s Explore tab gives you read access to its data.`,answer:!1,explain:`No. The catalog shows items you can access or can request access to. It doesn’t grant access by itself.`},{id:`s2`,text:`The OneLake catalog’s Secure tab shows workspace roles and OneLake security roles in one place.`,answer:!0,explain:`Yes. Learn lists Secure as the tab that brings workspace roles and OneLake security roles together.`},{id:`s3`,text:`A tenant admin must provision the Real-Time hub before anyone can browse streams.`,answer:!1,explain:`No. Every tenant gets a Real-Time hub automatically; there is nothing to provision.`}]},{id:`VS-H1`,machineId:c,bulletIds:[`P1.4`],format:`single`,difficulty:3,trapPairId:`stores`,stem:`A data engineering team writes all its transformations in PySpark and stores JSON logs and product images alongside tabular sales data. Report authors only read the curated data with T-SQL. No process needs multi-table transactions. A team lead argues that a warehouse is required because the report authors use T-SQL. Which store should you recommend?`,sources:[t.decisionStore,t.decisionLhWh,t.endpoint],options:[{id:`a`,text:`A warehouse, because the report authors query with T-SQL`,explain:`T-SQL readers don’t require a warehouse. Learn’s scenario picks a lakehouse when developers use PySpark and T-SQL users only consume data through the SQL analytics endpoint.`},{id:`b`,text:`A lakehouse, with the report authors reading through its SQL analytics endpoint`,explain:`Correct. Spark-first development, semi-structured and unstructured files, and no multi-table transactions all point to a lakehouse; its read-only SQL analytics endpoint serves the T-SQL readers.`},{id:`c`,text:`An eventhouse, because the JSON logs are semi-structured`,explain:`An eventhouse is for streaming events and KQL analytics. Semi-structured files alone don’t call for one.`},{id:`d`,text:`A SQL database in Fabric, so report authors get a SQL analytics endpoint`,explain:`SQL database in Fabric is for operational (OLTP) workloads, not a Spark-based analytics team with files.`}],answer:`b`},{id:`RB-H1`,machineId:l,bulletIds:[`P2.1`],format:`single`,difficulty:3,trapPairId:`endpoint-vs-warehouse`,stem:`Curated tables live in a lakehouse. You want a T-SQL stored procedure, run nightly by a pipeline, that reads those tables and writes a monthly summary table. You first try to create it on the lakehouse’s SQL analytics endpoint. What should you do?`,sources:[t.endpoint,t.tsqlSurface,t.queryWarehouse,t.createProc],options:[{id:`a`,text:`Create the procedure on the SQL analytics endpoint; it can insert into lakehouse tables when a pipeline runs it`,explain:`You can create a procedure on the endpoint, but the endpoint is read-only for INSERT, UPDATE, and DELETE, whoever runs it.`},{id:`b`,text:`Create the procedure in a warehouse in the same workspace, read the lakehouse tables with three-part names, and write the summary to a warehouse table`,explain:`Correct. A warehouse supports full DML, and cross-database queries read lakehouse tables in the same workspace by three-part name.`},{id:`c`,text:`Create an inline table-valued function on the endpoint and save its result as a table`,explain:`Functions return results; they can’t write tables on the read-only endpoint.`},{id:`d`,text:`Create a view on the endpoint and grant the pipeline INSERT on the view`,explain:`A view doesn’t store data, and the endpoint still won’t accept INSERT.`}],answer:`b`},{id:`RB-H2`,machineId:l,bulletIds:[`P2.1`],format:`single`,difficulty:3,trapPairId:`star-vs-snowflake`,stem:`A warehouse stores the product dimension as three normalized tables: Product, Subcategory, and Category. A semantic model needs a Category > Subcategory > Product hierarchy, and a regional team must be able to query the product data without being granted access to the base tables. What should you create?`,sources:[t.dimTables,t.createView,t.whGranular],options:[{id:`a`,text:`Three model tables related in a chain, with the hierarchy built across them`,explain:`A model hierarchy can only use columns from one table, so a chain of three tables can’t hold it.`},{id:`b`,text:`A stored procedure that returns the joined rows each time the model refreshes`,explain:`This doesn’t give the team a secured slice; Learn’s approach is a view that joins the tables, with permissions granted on the view.`},{id:`c`,text:`Primary and foreign key constraints between the tables so the model detects the hierarchy`,explain:`Constraints in a warehouse are NOT ENFORCED metadata. They don’t flatten the dimension or limit what users see.`},{id:`d`,text:`A view that joins the three tables into one denormalized product result, with permissions granted on the view`,explain:`Correct. Learn suggests exposing a snowflake dimension through a view that joins it back into one table, and a view lets users read data through it without permissions on the underlying base tables.`}],answer:`d`},{id:`DV-H1`,machineId:u,bulletIds:[`P2.2`],format:`single`,difficulty:3,stem:`A GrossRevenue column (unit price × quantity) is needed by Spark notebooks, by analysts using the lakehouse’s SQL analytics endpoint, and by two different semantic models. Each consumer must get the same value. Where should you add the column?`,sources:[t.loadTables,t.lakehousePrep,t.onelake],options:[{id:`a`,text:`As a DAX calculated column in each semantic model`,explain:`A DAX calculated column exists only inside one semantic model. Notebooks and the SQL endpoint wouldn’t see it, and two models could drift apart.`},{id:`b`,text:`In the notebook that writes the Delta table, with withColumn() before the write`,explain:`Correct. A column derived in the ETL is stored once in the table, so every engine that reads OneLake gets the same value.`},{id:`c`,text:`As a measure in each report`,explain:`Report measures live in a report and aren’t visible to notebooks or the SQL endpoint.`},{id:`d`,text:`In a KQL queryset that every consumer runs first`,explain:`A KQL queryset queries KQL databases. It doesn’t add a stored column to lakehouse tables.`}],answer:`b`},{id:`WP-H1`,machineId:d,bulletIds:[`P2.3`],format:`order`,difficulty:3,trapPairId:`scd1-vs-scd2`,stem:`You are building the nightly load for a warehouse star schema. The customer dimension uses SCD type 2 and has generated surrogate keys. Put the load steps in order.`,sources:[t.loadTables,t.dimTables],items:[{id:`i1`,text:`Load new fact rows, looking up each dimension’s current surrogate key`,explain:`Fourth. Facts are loaded after the dimensions so every lookup finds the current version of the member.`},{id:`i2`,text:`Land the source extracts in a staging schema that business users never see`,explain:`First. Learn recommends staging source data in a separate schema.`},{id:`i3`,text:`Process the customer dimension: expire changed rows and insert new versions`,explain:`Third. Type 2 changes expire the current row and insert a new versioned row with a new surrogate key.`},{id:`i4`,text:`Clean and conform the staged data: types, nulls, and duplicates`,explain:`Second. Fix the data in staging before it reaches the dimensional tables.`}],answerOrder:[`i2`,`i4`,`i3`,`i1`]},{id:`WP-H2`,machineId:d,bulletIds:[`P2.4`],format:`multi`,difficulty:3,stem:`A warehouse receives normalized source tables for customers, cities, and countries. Analysts and a semantic model need one denormalized customer dimension. Which two approaches meet the need? Choose two.`,sources:[t.dimTables,t.loadTables,t.tsqlSurface],options:[{id:`a`,text:`Load a customer dimension table with CREATE TABLE AS SELECT that joins the three tables`,explain:`Correct. Joining in the ETL (CTAS or INSERT…SELECT) flattens the levels into one dimension table.`},{id:`b`,text:`Add NOT ENFORCED foreign keys from customer to city and country`,explain:`Constraints are metadata only. The data stays normalized across three tables.`},{id:`c`,text:`Create a view that joins the three tables into one result`,explain:`Correct. Learn also suggests a view over normalized tables to present one denormalized dimension.`},{id:`d`,text:`Truncate and reload the three tables every night`,explain:`Reloading doesn’t change the structure, and Learn warns against truncating dimensions with generated surrogate keys.`}],answers:[`a`,`c`]},{id:`WP-H3`,machineId:d,bulletIds:[`P2.4`,`P2.3`],format:`single`,difficulty:3,stem:`A source system deletes discontinued products. The warehouse product dimension uses generated surrogate keys and SCD type 2 history, and years of sales facts reference it. A developer proposes truncating and reloading the dimension nightly from the source so that deleted products disappear. What should you do instead?`,sources:[t.loadTables,t.dimTables],options:[{id:`a`,text:`Keep the rows and record source deletions as soft deletes in a column such as IsDeleted`,explain:`Correct. Learn says never to truncate and reload a dimension with generated surrogate keys, because it breaks fact references and type 2 history; record deletions as soft deletes.`},{id:`b`,text:`Truncate and reload, then rebuild the fact table so the keys line up again`,explain:`Rebuilding facts to match regenerated keys loses the type 2 history and is the full reload Learn calls a last resort.`},{id:`c`,text:`Delete the product rows and their fact rows in one transaction`,explain:`Deleting facts removes real sales history from reports.`},{id:`d`,text:`Convert the dimension to SCD type 3 so deleted products move to a previous-value column`,explain:`Type 3 tracks limited history in extra columns; it isn’t a way to handle deletions, and Learn suggests type 2 over type 3 for semantic models.`}],answer:`a`},{id:`TF-H1`,machineId:f,bulletIds:[`P2.5`],format:`single`,difficulty:2,stem:`A sales fact table has one row per order line. Most reports only need monthly totals by product and store, and the team wants faster summary queries. Auditors still occasionally look up single orders by sales order number. What should you do?`,sources:[t.loadTables,t.ingestWarehouse],options:[{id:`a`,text:`Replace the fact table with a monthly aggregate grouped by product and store`,explain:`Aggregating raises the grain and loses the order detail for good, which the auditors still need.`},{id:`b`,text:`Drop the sales order number column to reduce the table size`,explain:`That removes exactly the column the auditors use.`},{id:`c`,text:`Keep the detail fact table, and build a separate monthly aggregate table with CREATE TABLE AS SELECT … GROUP BY`,explain:`Correct. A CTAS with GROUP BY materializes the summary for fast reporting while the detail table keeps the grain that order lookups need.`},{id:`d`,text:`Add a calculated column with the monthly total to every order line`,explain:`Repeating totals on every row doesn’t reduce what summary queries scan and duplicates the aggregation logic.`}],answer:`c`},{id:`TF-H2`,machineId:f,bulletIds:[`P2.6`],format:`single`,difficulty:3,stem:`A warehouse in the Sales workspace must join its fact table to a customer table that lives in a lakehouse in the CRM workspace. A cross-database query with a three-part name fails. What should you do so the warehouse can join the data without copying it?`,sources:[t.queryWarehouse,t.shortcuts,t.ingestWarehouse],options:[{id:`a`,text:`Use a four-part name that includes the CRM workspace`,explain:`Fabric cross-database queries use three-part names, and they work only within the same workspace.`},{id:`b`,text:`Grant the warehouse’s users the Viewer role on the CRM workspace`,explain:`Permissions don’t remove the same-workspace limit on cross-database queries.`},{id:`c`,text:`Run COPY INTO from the CRM lakehouse’s Tables folder every night`,explain:`COPY INTO makes a copy, which the requirement rules out.`},{id:`d`,text:`Create a OneLake shortcut to the CRM customer table in a lakehouse in the Sales workspace, then join to that lakehouse with a three-part name`,explain:`Correct. A shortcut references the data in place from another workspace, and the warehouse can then join the local lakehouse by three-part name.`}],answer:`d`},{id:`CM-H1`,machineId:p,bulletIds:[`P2.7`],format:`dropdown`,difficulty:3,trapPairId:`where-having-qualify`,stem:`A staging table holds several versions of each customer, and some rows have a NULL region. Load one row per CustomerID (the most recently modified version) and show missing regions as Unknown. Complete the T-SQL.`,sources:[t.qualify,t.coalesce],language:`tsql`,code:`SELECT CustomerID,
       [[1]](Region, 'Unknown') AS Region,
       ModifiedAt
FROM staging.Customer
[[2]] ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY ModifiedAt [[3]]) = 1;`,slots:[{id:`1`,options:[{id:`a`,text:`TRY_CAST`,explain:`TRY_CAST converts one value to a data type; it doesn’t replace NULL with a default.`},{id:`b`,text:`COALESCE`,explain:`Correct. COALESCE returns the first non-NULL argument, so a NULL region becomes Unknown.`},{id:`c`,text:`CONCAT`,explain:`CONCAT joins strings, so it would append Unknown to every region, not replace only the NULL ones.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`QUALIFY`,explain:`Correct. QUALIFY filters after window functions are evaluated, so it can keep row number 1 without a subquery.`},{id:`b`,text:`WHERE`,explain:`WHERE runs before window functions, so it can’t reference ROW_NUMBER().`},{id:`c`,text:`HAVING`,explain:`HAVING filters groups after GROUP BY; there is no GROUP BY here, and it runs before window functions.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`ASC`,explain:`Ascending would number the oldest version 1 and keep it.`},{id:`b`,text:`DESC`,explain:`Correct. Descending order numbers the most recently modified version 1.`},{id:`c`,text:`NULLS LAST`,explain:`NULLS LAST only controls where NULLs sort; it doesn’t make the newest version row number 1, which needs DESC.`}],answer:`b`}]},{id:`CM-H2`,machineId:p,bulletIds:[`P2.7`],format:`yesno`,difficulty:3,stem:`You are cleaning sales data before loading a warehouse star schema. Some fact rows reference customers that aren’t in the customer dimension, and the source has duplicate rows. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.qualify,t.dimTables,t.loadTables,t.dataWrangler],statements:[{id:`s1`,text:`Mapping fact rows whose customer lookup fails to an Unknown member keeps them in the fact table with a valid key.`,answer:!0,explain:`Yes. Learn recommends special members such as Unknown so a failed lookup still gets a valid dimension key.`},{id:`s2`,text:`WHERE ROW_NUMBER() OVER (PARTITION BY OrderID ORDER BY LoadedAt DESC) = 1 removes the duplicates in one SELECT.`,answer:!1,explain:`No. WHERE runs before window functions, so it can’t reference ROW_NUMBER(). Use QUALIFY, a CTE, or a subquery.`},{id:`s3`,text:`In a notebook, Data Wrangler’s Drop duplicate rows operation generates code you can export back to the notebook.`,answer:!0,explain:`Yes. Data Wrangler operations generate pandas or PySpark code that you can export to the notebook.`}]},{id:`CM-H3`,machineId:p,bulletIds:[`P2.8`],format:`single`,difficulty:3,stem:`You are recreating a SQL Server table in a Fabric warehouse. The source columns are Amount money, CreatedAt datetime, Notes nvarchar(200), and Priority tinyint. Which column definitions follow Learn’s guidance for warehouse tables?`,sources:[t.dataTypes],options:[{id:`a`,text:`Amount decimal(19,4), CreatedAt datetime2(6), Notes varchar(200), Priority smallint`,explain:`Correct. Learn maps money to decimal, datetime to datetime2 (up to 6 fractional digits), nvarchar to varchar, and tinyint to smallint.`},{id:`b`,text:`Amount money, CreatedAt datetime2(6), Notes varchar(200), Priority smallint`,explain:`money isn’t supported in warehouse tables; use decimal.`},{id:`c`,text:`Amount decimal(19,4), CreatedAt datetime, Notes varchar(200), Priority smallint`,explain:`datetime isn’t supported in warehouse tables; use datetime2.`},{id:`d`,text:`Amount decimal(19,4), CreatedAt datetime2(7), Notes nvarchar(200), Priority tinyint`,explain:`nvarchar and tinyint aren’t supported, and datetime2 is limited to 6 fractional-second digits.`}],answer:`a`},{id:`CM-H4`,machineId:p,bulletIds:[`P2.9`],format:`match`,difficulty:3,trapPairId:`where-having-qualify`,stem:`A warehouse query must apply three filters. Match each filter to the T-SQL clause that applies it at the right point in query processing.`,sources:[t.qualify,t.groupBy],prompts:[{id:`p1`,text:`Keep only orders placed in 2026, before anything is grouped`},{id:`p2`,text:`Keep only customers whose order count is above 5 after GROUP BY`},{id:`p3`,text:`Keep each customer’s newest row after ROW_NUMBER() is calculated`}],choices:[{id:`c1`,text:`WHERE`},{id:`c2`,text:`HAVING`},{id:`c3`,text:`QUALIFY`},{id:`c4`,text:`ORDER BY`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`WHERE filters individual rows before grouping and window functions.`},{promptId:`p2`,choiceId:`c2`,explain:`HAVING filters grouped results after GROUP BY.`},{promptId:`p3`,choiceId:`c3`,explain:`QUALIFY filters after window functions are evaluated. ORDER BY (unused) only sorts and filters nothing.`}]},{id:`IB-H1`,machineId:m,bulletIds:[`P3.1`],format:`single`,difficulty:3,trapPairId:`visual-vs-sql-editor`,stem:`An analyst who doesn’t write SQL builds a visual query that merges two warehouse tables and groups the result. She must save the result as a new table, and later a colleague wants to tweak the logic in T-SQL. Which approach meets both needs?`,sources:[t.visualQuery],options:[{id:`a`,text:`Add a DDL step to the visual query that inserts the result into a table`,explain:`The visual query editor runs read-only SELECT queries; it can’t run DDL or DML steps.`},{id:`b`,text:`Visualize the results with an ORDER BY step, then export the chart data`,explain:`Visualize results doesn’t support queries with ORDER BY, and exporting a chart doesn’t create a table.`},{id:`c`,text:`Save the visual query as a view, then insert from the view in the visual editor`,explain:`A view stores no data, and the visual editor can’t run INSERT.`},{id:`d`,text:`Use Save as table, and give the colleague the T-SQL from View SQL to open in the SQL editor`,explain:`Correct. Save as table creates the table with CREATE TABLE AS SELECT, and View SQL shows the generated T-SQL that can be opened in the SQL editor.`}],answer:`d`},{id:`IB-H2`,machineId:m,bulletIds:[`P3.2`],format:`single`,difficulty:3,stem:`In the Sales workspace, a warehouse named SalesWH holds dbo.FactSales, and a lakehouse named RefLake holds dbo.Store. In SalesWH’s SQL query editor you must return total sales per store name. Which query works?`,sources:[t.queryWarehouse,t.groupBy],options:[{id:`a`,text:`SELECT s.StoreName, SUM(f.Amount) AS Sales FROM dbo.FactSales AS f JOIN dbo.Store AS s ON f.StoreKey = s.StoreKey GROUP BY s.StoreName;`,explain:`dbo.Store without an item name refers to SalesWH, which has no Store table.`},{id:`b`,text:`SELECT s.StoreName, SUM(f.Amount) AS Sales FROM dbo.FactSales AS f JOIN RefLake.dbo.Store AS s ON f.StoreKey = s.StoreKey GROUP BY s.StoreName;`,explain:`Correct. A three-part name (item.schema.table) reads the lakehouse table in the same workspace, and GROUP BY returns one row per store.`},{id:`c`,text:`SELECT s.StoreName, SUM(f.Amount) AS Sales FROM dbo.FactSales AS f JOIN Sales.RefLake.dbo.Store AS s ON f.StoreKey = s.StoreKey GROUP BY s.StoreName;`,explain:`Fabric cross-database queries use three-part names; a workspace prefix isn’t part of the syntax.`},{id:`d`,text:`SELECT s.StoreName, SUM(f.Amount) AS Sales FROM dbo.FactSales AS f JOIN RefLake.dbo.Store AS s ON f.StoreKey = s.StoreKey;`,explain:`This drops GROUP BY, so it doesn’t return one total per store.`}],answer:`b`},{id:`KT-H1`,machineId:`tension-meter`,bulletIds:[`P3.3`],format:`dropdown`,difficulty:2,trapPairId:`project-vs-extend`,stem:`In a KQL queryset you need the number of error events per hour over the last day, busiest hour first. Complete the query.`,sources:[t.kqlSummarize,t.kqlBin,t.kqlSort],language:`kql`,code:`AppEvents
| where Timestamp > ago(1d)
| [[1]] Errors = countif(Level == "Error") by [[2]](Timestamp, 1h)
| [[3]] Errors desc`,slots:[{id:`1`,options:[{id:`a`,text:`extend`,explain:`extend adds a column to every row; it doesn’t group rows or support by.`},{id:`b`,text:`summarize`,explain:`Correct. summarize groups rows by the by expressions and computes the aggregation for each group.`},{id:`c`,text:`project`,explain:`project chooses or computes columns per row; it doesn’t aggregate.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`bin`,explain:`Correct. bin() rounds each timestamp down to a 1-hour range, which you must state explicitly in summarize.`},{id:`b`,text:`ago`,explain:`ago() returns a point in time relative to now; it doesn’t group values into ranges.`},{id:`c`,text:`count`,explain:`count is an aggregation, not a grouping expression.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`take`,explain:`take returns arbitrary rows; it doesn’t sort.`},{id:`b`,text:`distinct`,explain:`distinct removes duplicate rows; it doesn’t order them.`},{id:`c`,text:`sort by`,explain:`Correct. sort by orders the rows; desc puts the busiest hour first.`}],answer:`c`}]}],g=`tension-meter`,_=`dax-scale`,v=[{id:`KT-01`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:1,trapPairId:`sql-vs-kql`,stem:`You are querying the StormEvents table in a KQL database. You need to keep only the rows where State is TEXAS. Which line should follow the table name?`,sources:[t.kqlWhere,t.sqlToKql],options:[{id:`a`,text:`WHERE State = 'TEXAS'`,explain:`This is SQL syntax. KQL pipes the table into the where operator and uses == for equality.`},{id:`b`,text:`| where State == 'TEXAS'`,explain:`Correct. where filters rows on a predicate, and == is equality in KQL.`},{id:`c`,text:`| extend State == 'TEXAS'`,explain:`extend adds a calculated column; it doesn’t remove rows.`},{id:`d`,text:`| project State == 'TEXAS'`,explain:`project chooses or computes columns; it doesn’t filter rows.`}],answer:`b`},{id:`KT-02`,machineId:g,bulletIds:[`P3.3`],format:`dropdown`,difficulty:2,stem:`You need the number of Texas storm events per hour, oldest hour first, from a KQL database. Complete the KQL query.`,sources:[t.kqlSummarize,t.kqlBin,t.kqlSort],language:`kql`,code:`StormEvents
| where State == 'TEXAS'
| [[1]] EventCount = count() by [[2]](StartTime, 1h)
| [[3]] by StartTime asc`,slots:[{id:`1`,options:[{id:`a`,text:`extend`,explain:`extend adds a column to every row; it doesn’t group rows or aggregate.`},{id:`b`,text:`summarize`,explain:`Correct. summarize groups rows by the by expressions and computes count() per group.`},{id:`c`,text:`project`,explain:`project chooses columns; it can’t group by.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`bin`,explain:`Correct. bin(StartTime, 1h) rounds each time down to its hour bucket.`},{id:`b`,text:`ago`,explain:`ago() returns a time relative to now; it doesn’t bucket values.`},{id:`c`,text:`between`,explain:`between tests whether a value falls in a range inside a where filter.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`top`,explain:`top needs a row count, such as top 10 by StartTime.`},{id:`b`,text:`take`,explain:`take returns arbitrary rows and doesn’t accept by.`},{id:`c`,text:`sort`,explain:`Correct. sort by StartTime asc orders the buckets oldest first.`}],answer:`c`}]},{id:`KT-03`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:1,trapPairId:`project-vs-extend`,stem:`You need to add a Duration column (EndTime minus StartTime) to the StormEvents results while keeping every existing column. Which KQL line should you use?`,sources:[t.kqlExtend,t.kqlOperators],options:[{id:`a`,text:`| project Duration = EndTime - StartTime`,explain:`project returns only the columns listed, so every other column would be dropped.`},{id:`b`,text:`| summarize Duration = EndTime - StartTime`,explain:`summarize needs an aggregation function and changes the grain.`},{id:`c`,text:`| extend Duration = EndTime - StartTime`,explain:`Correct. extend appends the calculated column and keeps all existing columns.`},{id:`d`,text:`| where Duration = EndTime - StartTime`,explain:`where filters rows on a condition; it can’t define a column.`}],answer:`c`},{id:`KT-04`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:2,stem:`You need the five storm events with the highest DamageProperty from a KQL table. Which query returns them?`,sources:[t.kqlTop,t.kqlTake],options:[{id:`a`,text:`StormEvents | take 5 | sort by DamageProperty`,explain:`take picks 5 arbitrary rows first, then sorts only those five.`},{id:`b`,text:`StormEvents | top 5 by DamageProperty`,explain:`Correct. top returns the first 5 rows by DamageProperty, descending by default.`},{id:`c`,text:`StormEvents | sort by DamageProperty asc | take 5`,explain:`Sorting ascending puts the lowest damage first, so this returns the smallest five.`},{id:`d`,text:`StormEvents | where DamageProperty > 5`,explain:`This keeps every row with damage above 5, not the top five rows.`}],answer:`b`},{id:`KT-05`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:2,trapPairId:`sql-vs-kql`,stem:`A SQL developer writes StormEvents | sort by StartTime in a KQL queryset and expects the oldest events first. What does the query return?`,sources:[t.kqlOperators,t.kqlSort],options:[{id:`a`,text:`The oldest events first, like ORDER BY in SQL`,explain:`Unlike SQL ORDER BY, KQL sort defaults to descending.`},{id:`b`,text:`An error, because sort needs asc or desc`,explain:`The direction is optional; the query runs with the default.`},{id:`c`,text:`Rows in arbitrary order, because sort needs a top`,explain:`sort works on its own and orders every row.`},{id:`d`,text:`The newest events first`,explain:`Correct. The default sort order is descending; add asc for oldest first.`}],answer:`d`},{id:`KT-06`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:3,stem:`A KQL query joins Orders to Shipments on OrderId with | join Shipments on OrderId and no kind. Orders has several rows per OrderId, and the result has fewer rows than expected. What explains this, and what should you change?`,sources:[t.kqlJoin],options:[{id:`a`,text:`The default flavor is innerunique, which de-duplicates the left side’s keys; specify kind=inner`,explain:`Correct. Learn: the default join is innerunique (inner join with left-side deduplication). kind=inner keeps every matching row.`},{id:`b`,text:`The default flavor is leftanti, which keeps only the left rows without a match; specify kind=leftouter`,explain:`leftanti isn’t the default; Learn names innerunique as the default.`},{id:`c`,text:`Joins need a summarize before them; add summarize by OrderId`,explain:`Summarizing first would reduce the left rows even more.`},{id:`d`,text:`KQL joins only on datetime columns; convert OrderId with todatetime()`,explain:`KQL joins on any matching columns; there’s no datetime requirement.`}],answer:`a`},{id:`KT-07`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:2,stem:`You join a small DeviceInfo table (500 rows) to a large Telemetry table (2 billion rows) in KQL. You want the best join performance. How should you write the join?`,sources:[t.kqlJoin],options:[{id:`a`,text:`Put Telemetry on the left and DeviceInfo on the right`,explain:`Learn recommends the opposite: the smaller table on the left.`},{id:`b`,text:`Put DeviceInfo on the left side of the join`,explain:`Correct. Learn: if one table is always smaller, use it as the left side of the join.`},{id:`c`,text:`Run take 500 on Telemetry before the join`,explain:`take returns arbitrary rows, which would silently lose data.`},{id:`d`,text:`Use kind=fullouter so both sides are scanned once`,explain:`Changing the flavor changes the results; it isn’t a performance setting.`}],answer:`b`},{id:`KT-08`,machineId:g,bulletIds:[`P3.3`],format:`match`,difficulty:1,trapPairId:`sql-vs-kql`,stem:`A SQL developer is moving to KQL. Match each SQL construct to its KQL equivalent.`,sources:[t.sqlToKql],prompts:[{id:`p1`,text:`SELECT name, type`},{id:`p2`,text:`WHERE type = 'blob'`},{id:`p3`,text:`GROUP BY name with COUNT(*)`},{id:`p4`,text:`SELECT TOP 100 … ORDER BY Count DESC`}],choices:[{id:`c1`,text:`| project name, type`},{id:`c2`,text:`| where type == "blob"`},{id:`c3`,text:`| summarize count() by name`},{id:`c4`,text:`| top 100 by Count desc`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`project chooses the output columns, like a SELECT list.`},{promptId:`p2`,choiceId:`c2`,explain:`where filters rows; KQL uses == for equality.`},{promptId:`p3`,choiceId:`c3`,explain:`summarize combines the aggregation and the grouping in one operator.`},{promptId:`p4`,choiceId:`c4`,explain:`top n by replaces SELECT TOP with ORDER BY.`}]},{id:`KT-09`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:2,trapPairId:`sql-vs-kql`,stem:`You know SQL well and want a KQL queryset to show you the KQL equivalent of a SQL query you wrote. What should you do?`,sources:[t.sqlToKql],options:[{id:`a`,text:`Run the SQL query in the warehouse SQL query editor and select View SQL`,explain:`View SQL belongs to the visual query editor and shows SQL, not KQL.`},{id:`b`,text:`Wrap the SQL query in a summarize operator`,explain:`summarize is a KQL operator; it can’t contain a SQL query.`},{id:`c`,text:`Put a comment line (--) and the keyword explain before the SQL query`,explain:`Correct. Learn: preface the SQL query with a comment line and explain, and the output shows the KQL version.`},{id:`d`,text:`Open the query in DAX query view`,explain:`DAX query view runs DAX against semantic models.`}],answer:`c`},{id:`KT-10`,machineId:g,bulletIds:[`P3.3`],format:`yesno`,difficulty:2,stem:`You are reviewing KQL queries written by a new team member. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.kqlTake,t.kqlSummarize,t.kqlOperators],statements:[{id:`s1`,text:`take 10 returns up to ten rows with no guarantee which rows are returned.`,answer:!0,explain:`Yes. take returns up to the specified number of rows with no guarantee which ones; it suits a quick look at the data.`},{id:`s2`,text:`Aggregation functions such as sum() and avg() in summarize ignore null values.`,answer:!0,explain:`Yes. Learn: null values are ignored by these aggregates (the standard count() is the exception and includes nulls).`},{id:`s3`,text:`summarize count() by StartTime automatically groups a datetime column into hourly bins.`,answer:!1,explain:`No. Automatic hourly bins are no longer supported; use bin(StartTime, 1h) explicitly.`}]},{id:`KT-11`,machineId:g,bulletIds:[`P3.3`],format:`order`,difficulty:2,stem:`You need flood events counted per 30-day bucket, oldest bucket first. Put the lines of the KQL query in order.`,sources:[t.kqlOperators,t.kqlSummarize],items:[{id:`i3`,text:`| summarize Events = count() by bin(StartTime, 30d)`,explain:`Third. Aggregate the filtered rows into 30-day buckets. After this, EventType no longer exists, so the filter must come first.`},{id:`i4`,text:`| sort by StartTime asc`,explain:`Last. Sort the buckets oldest first; sort defaults to descending without asc.`},{id:`i1`,text:`StormEvents`,explain:`First. A KQL query starts from the table and pipes it through operators.`},{id:`i2`,text:`| where EventType == 'Flood'`,explain:`Second. Filter to flood events while the EventType column still exists.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`KT-12`,machineId:g,bulletIds:[`P3.3`],format:`multi`,difficulty:3,trapPairId:`sql-vs-kql`,stem:`For each name in the dependencies table, you need the number of distinct type values. A fast estimate is acceptable. Which two KQL queries meet the goal? Choose two.`,sources:[t.sqlToKql,t.kqlDcount],options:[{id:`a`,text:`dependencies | summarize count() by name, type`,explain:`This counts rows per name and type pair, not distinct types per name.`},{id:`b`,text:`dependencies | summarize dcount(type) by name`,explain:`Correct. dcount() returns an estimate of the distinct values per group, which the stem allows; Learn’s cheat sheet maps COUNT(DISTINCT) to it.`},{id:`c`,text:`dependencies | summarize by name, type | summarize count() by name`,explain:`Correct. The first summarize leaves one row per name and type; the second counts them per name, giving an exact count.`},{id:`d`,text:`dependencies | distinct name | count`,explain:`This returns the number of distinct names, a single value.`}],answers:[`b`,`c`]},{id:`KT-13`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:1,stem:`You need the storm events that started between 00:00:00 on August 1, 2007, and 23:59:59 on August 30, 2007. Which KQL filter should you use?`,sources:[t.kqlWhere,t.kqlOperators],options:[{id:`a`,text:`| where StartTime > ago(30d)`,explain:`ago() is relative to now, so this returns the last 30 days, not August 2007.`},{id:`b`,text:`| summarize by bin(StartTime, 30d)`,explain:`This groups rows into buckets; it doesn’t filter a date range.`},{id:`c`,text:`| where StartTime in (datetime(2007-08-01 00:00:00), datetime(2007-08-30 00:00:00))`,explain:`in keeps only rows equal to one of the listed values, so this matches just those two exact instants.`},{id:`d`,text:`| where StartTime between (datetime(2007-08-01 00:00:00) .. datetime(2007-08-30 23:59:59))`,explain:`Correct. between filters on an inclusive range of values.`}],answer:`d`},{id:`KT-14`,machineId:g,bulletIds:[`P3.3`],format:`single`,difficulty:1,stem:`Your team needs a Fabric item in which to write, save, and run KQL queries against a KQL database in an eventhouse. What should you create?`,sources:[t.kqlQueryset],options:[{id:`a`,text:`A KQL queryset`,explain:`Correct. A KQL queryset is where you write, save, and run KQL queries against KQL databases.`},{id:`b`,text:`A SQL query in a warehouse`,explain:`The warehouse SQL editor runs T-SQL against warehouses and endpoints.`},{id:`c`,text:`A DAX query in DAX query view`,explain:`DAX query view runs DAX against semantic models.`},{id:`d`,text:`A Data Wrangler session in a notebook`,explain:`Data Wrangler cleans pandas or Spark DataFrames in notebooks.`}],answer:`a`},{id:`DS-01`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:1,placement:!0,stem:`You are writing your first DAX query in DAX query view to inspect a semantic model table. Which keyword must every DAX query contain?`,sources:[t.daxQueries],options:[{id:`a`,text:`DEFINE`,explain:`DEFINE is optional; it adds query-scoped definitions.`},{id:`b`,text:`ORDER BY`,explain:`ORDER BY is optional; it sorts the result.`},{id:`c`,text:`EVALUATE`,explain:`Correct. EVALUATE followed by a table expression is the one required keyword.`},{id:`d`,text:`START AT`,explain:`START AT is optional and only used inside ORDER BY.`}],answer:`c`},{id:`DS-02`,machineId:_,bulletIds:[`P3.4`],format:`dropdown`,difficulty:2,placement:!0,trapPairId:`query-measure-vs-model-measure`,stem:`You need to test a new measure against a semantic model without changing the model, returning orders by month in calendar order. Complete the DAX query.`,sources:[t.daxQueries],language:`dax`,code:`[[1]]
  MEASURE Sales[Avg Profit per Order] = DIVIDE([Total Sales Profit], [Orders])
[[2]]
SUMMARIZECOLUMNS(
  'Date'[Month Name], 'Date'[Month of Year],
  "Avg Profit per Order", [Avg Profit per Order]
)
[[3]] 'Date'[Month of Year] ASC`,slots:[{id:`1`,options:[{id:`a`,text:`DEFINE`,explain:`Correct. DEFINE introduces query-scoped definitions such as MEASURE.`},{id:`b`,text:`VAR`,explain:`VAR defines a variable inside DEFINE or an expression; it can’t introduce a MEASURE.`},{id:`c`,text:`CALCULATE`,explain:`CALCULATE is a function that modifies filter context, not a query keyword.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`RETURN`,explain:`RETURN ends a VAR block in an expression; queries use EVALUATE.`},{id:`b`,text:`EVALUATE`,explain:`Correct. EVALUATE runs the table expression and returns its result.`},{id:`c`,text:`SELECT`,explain:`SELECT is SQL; DAX queries use EVALUATE.`}],answer:`b`},{id:`3`,options:[{id:`a`,text:`START AT`,explain:`START AT sets where results begin and must be used inside ORDER BY.`},{id:`b`,text:`SORT BY`,explain:`SORT BY isn’t a DAX query keyword.`},{id:`c`,text:`ORDER BY`,explain:`Correct. ORDER BY sorts the query result by Month of Year.`}],answer:`c`}]},{id:`DS-03`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:2,placement:!0,stem:`In DAX query view, you want to see the value of the [Total Sales] measure for the whole model as a one-cell result. Which query should you run?`,sources:[t.daxQueries],options:[{id:`a`,text:`EVALUATE [Total Sales]`,explain:`EVALUATE needs a table expression; a measure returns a scalar.`},{id:`b`,text:`EVALUATE {[Total Sales]}`,explain:`Correct. Curly braces make a table constructor, so the scalar is shown as a result table.`},{id:`c`,text:`DEFINE [Total Sales]`,explain:`DEFINE holds definitions and must be followed by EVALUATE; it doesn’t return results itself.`},{id:`d`,text:`SELECT [Total Sales]`,explain:`SELECT is SQL syntax, not DAX.`}],answer:`b`},{id:`DS-04`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:2,placement:!0,stem:`In the semantic model, Month Name is sorted by Month of Year. Your DAX query groups by Month Name, and the result lists April, August, December. You need calendar order. What should you do?`,sources:[t.daxQueries],options:[{id:`a`,text:`Set the Sort by column property on Month Name again`,explain:`Sort by column settings don’t apply to DAX query results, so this changes nothing.`},{id:`b`,text:`Add ORDER BY 'Date'[Month Name] ASC to the end of the query`,explain:`Sorting by the name itself is still alphabetical.`},{id:`c`,text:`Wrap the query in TOPN with 12 rows`,explain:`TOPN limits rows; it doesn’t produce calendar order.`},{id:`d`,text:`Include 'Date'[Month of Year] in the query and ORDER BY it`,explain:`Correct. Learn: the sort-by column must be included in the DAX query and used in ORDER BY.`}],answer:`d`},{id:`DS-05`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:2,placement:!0,trapPairId:`query-measure-vs-model-measure`,stem:`A model already has a measure named [Margin]. In DAX query view, you write DEFINE MEASURE Sales[Margin] with a different formula and run the query. What happens?`,sources:[t.daxQueries,t.daxQueryView],options:[{id:`a`,text:`The query uses your formula and the model measure is unchanged`,explain:`Correct. DEFINE MEASURE is query-scoped: the query uses its formula, and the model changes only if you choose Update model.`},{id:`b`,text:`The model measure is overwritten with your formula as soon as the query runs`,explain:`Running the query doesn’t change the model; CodeLens or Update model with changes does.`},{id:`c`,text:`The query fails because the name already exists`,explain:`Overriding an existing measure for testing is a documented scenario.`},{id:`d`,text:`The query ignores your formula and uses the model measure`,explain:`When the measure exists, the query uses the formula defined in the query.`}],answer:`a`},{id:`DS-06`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:1,placement:!0,trapPairId:`query-measure-vs-model-measure`,stem:`You tested three new measures in a DEFINE block in DAX query view and want to add all of them to the semantic model at once. What should you use?`,sources:[t.daxQueryView],options:[{id:`a`,text:`The Update model with changes button`,explain:`Correct. It adds or overwrites model measures with all the query-scoped measures in the DEFINE block.`},{id:`b`,text:`Performance Analyzer’s Copy query action`,explain:`Copy query copies the DAX a visual sent; it doesn’t add measures.`},{id:`c`,text:`A new EVALUATE statement for each measure`,explain:`More EVALUATE statements return more results but never change the model.`},{id:`d`,text:`Save the query in the My queries folder`,explain:`Saving the query keeps the text; the measures stay query-scoped.`}],answer:`a`},{id:`DS-07`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:1,placement:!0,stem:`You work on a Mac and can’t run Power BI Desktop. You need to run DAX queries against a published semantic model from the browser. What should you do?`,sources:[t.daxQueryView],options:[{id:`a`,text:`Open the lakehouse SQL analytics endpoint and write the query in T-SQL instead of DAX`,explain:`The endpoint runs T-SQL against lakehouse tables, not DAX against a semantic model.`},{id:`b`,text:`Open a KQL queryset and paste the DAX`,explain:`KQL querysets run KQL, not DAX.`},{id:`c`,text:`Select Write DAX queries for the model in the workspace or on its details page`,explain:`Correct. Learn: in the Power BI service or Fabric portal, select Write DAX queries from the context menu or the details page.`},{id:`d`,text:`Create a visual query in the warehouse editor`,explain:`The visual query editor builds SQL queries against warehouses and endpoints.`}],answer:`c`},{id:`DS-08`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:3,placement:!0,stem:`You run EVALUATE TOPN(5, 'Product', [Total Sales], DESC) ORDER BY 'Product'[Product Name] ASC. What does the query return?`,sources:[t.daxQueries],options:[{id:`a`,text:`The first five products alphabetically by name`,explain:`ORDER BY doesn’t choose TOPN’s rows; TOPN ranks by its own argument.`},{id:`b`,text:`The five best-selling products, sorted by Total Sales descending`,explain:`TOPN picks the best sellers, but ORDER BY then sorts them by name.`},{id:`c`,text:`An error, because ORDER BY must match TOPN’s order`,explain:`The query is valid; the two orders are independent.`},{id:`d`,text:`The five best-selling products, sorted by product name`,explain:`Correct. TOPN picks rows by [Total Sales]; ORDER BY only sorts the rows TOPN returned.`}],answer:`d`},{id:`DS-09`,machineId:_,bulletIds:[`P3.4`],format:`yesno`,difficulty:2,placement:!0,stem:`You are writing a DAX query script for a semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.daxQueries],statements:[{id:`s1`,text:`A DAX query can contain several EVALUATE statements.`,answer:!0,explain:`Yes. Learn contrasts EVALUATE, which can repeat, with DEFINE, which can appear only once.`},{id:`s2`,text:`Each EVALUATE statement can have its own DEFINE block placed right before it.`,answer:!1,explain:`No. There can be only one DEFINE block; it must come before the first EVALUATE and applies to all of them.`},{id:`s3`,text:`Definitions in a DEFINE block exist only for the duration of the query.`,answer:!0,explain:`Yes. DEFINE introduces calculated entities that exist only while the query runs.`}]},{id:`DS-10`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:3,placement:!0,stem:`You are writing a SUMMARIZECOLUMNS query that groups by month, keeps only the Clothing category with FILTER(VALUES('Product'[Category]), [Category] = "Clothing"), and returns an "Orders" column. Where does the FILTER argument go?`,sources:[t.summarizeColumns,t.daxQueries],options:[{id:`a`,text:`After the group-by columns and before the "Orders", [Orders] pair`,explain:`Correct. The syntax is group-by columns, then filter tables, then name/expression pairs.`},{id:`b`,text:`After the "Orders", [Orders] pair, as the last argument of SUMMARIZECOLUMNS`,explain:`Name/expression pairs come last; a filter table can’t follow them.`},{id:`c`,text:`Before the group-by columns, as the first argument`,explain:`Group-by columns come first in SUMMARIZECOLUMNS.`},{id:`d`,text:`In the ORDER BY clause after EVALUATE`,explain:`ORDER BY sorts results; it doesn’t filter them.`}],answer:`a`},{id:`DS-11`,machineId:_,bulletIds:[`P3.4`],format:`single`,difficulty:2,placement:!0,stem:`A data engineer needs to run a DAX query against a semantic model from a Fabric notebook and work with the result in Python. What should they use?`,sources:[t.daxQueries],options:[{id:`a`,text:`Data Wrangler`,explain:`Data Wrangler cleans DataFrames; it doesn’t query semantic models.`},{id:`b`,text:`A Spark SQL cell against the model`,explain:`Spark SQL queries lakehouse tables, not semantic models.`},{id:`c`,text:`The lakehouse SQL analytics endpoint`,explain:`The endpoint runs T-SQL over lakehouse tables.`},{id:`d`,text:`Semantic link`,explain:`Correct. Learn: DAX queries can run in Fabric notebooks using semantic link to read semantic model data with Python.`}],answer:`d`}],y=`inspection-bench`,b=`recipe-book`,x=[{id:`IB-01`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:1,trapPairId:`visual-vs-sql-editor`,stem:`An analyst built a visual query on a Fabric warehouse that finds test orders. They now want the same editor to delete those rows from the table. What should you tell them?`,sources:[t.visualQuery,t.queryWarehouse],options:[{id:`a`,text:`Add a Remove rows step to the visual query, then select Save as table`,explain:`Save as table creates a new table with CTAS; it doesn’t delete rows from the source table.`},{id:`b`,text:`Write the DELETE in the SQL query editor instead`,explain:`Correct. The visual query editor runs only read-only SELECT queries. Learn: the visual query editor supports only DQL (read-only SELECT); DDL and DML aren’t supported.`},{id:`c`,text:`Select View SQL and run the generated script`,explain:`View SQL shows the SELECT generated from the steps; it doesn’t produce a DELETE.`},{id:`d`,text:`Enable load on the query, then refresh it`,explain:`Enable load picks which query appears in the SQL script; it doesn’t change data.`}],answer:`b`},{id:`IB-02`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:1,stem:`You built a visual query on a warehouse that filters and groups sales. A colleague wants to see the T-SQL that your steps produce so they can learn from it. Which feature should you use?`,sources:[t.visualQuery],options:[{id:`a`,text:`Visualize results`,explain:`Visualize results creates a report on the results; it doesn’t show the SQL.`},{id:`b`,text:`Download Excel file`,explain:`This exports the results to Excel, not the query text.`},{id:`c`,text:`View SQL`,explain:`Correct. View SQL shows the SQL query based on the applied steps of the visual query.`},{id:`d`,text:`Save as table`,explain:`Save as table writes the results into a table; it isn’t a way to read the SQL.`}],answer:`c`},{id:`IB-03`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:2,stem:`You need to persist the results of a visual query as a new table in a Fabric warehouse by using Save as table. Which T-SQL statement does the feature use to load the results?`,sources:[t.visualQuery],options:[{id:`a`,text:`CREATE TABLE AS SELECT`,explain:`Correct. Learn: Save as table loads the results into a table by using a CREATE TABLE AS SELECT statement.`},{id:`b`,text:`COPY INTO`,explain:`COPY INTO ingests files from storage, not the result of a query.`},{id:`c`,text:`SELECT … INTO a new table`,explain:`SELECT … INTO also creates a table, but Learn says Save as table uses CREATE TABLE AS SELECT.`},{id:`d`,text:`INSERT … VALUES`,explain:`INSERT … VALUES adds literal rows, not a query result.`}],answer:`a`},{id:`IB-04`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:3,stem:`In the visual query editor, Save as view is blocked and a banner says: “The query is not supported as a warehouse view, since it cannot be fully translated to SQL.” What is the most likely cause?`,sources:[t.visualQuery],options:[{id:`a`,text:`Your role doesn’t allow creating views in any schema`,explain:`A permission problem would surface when choosing a schema, not as a translation banner.`},{id:`b`,text:`The query has an ORDER BY clause`,explain:`The ORDER BY limitation applies to Visualize results, not to saving a view.`},{id:`c`,text:`The editor is open on a SQL analytics endpoint, not a warehouse`,explain:`The visual query editor and saving views work on SQL analytics endpoints too.`},{id:`d`,text:`A step in the query can’t be folded into SQL`,explain:`Correct. Only Power Query operations that support query folding are supported, and steps that can’t be translated block the view.`}],answer:`d`},{id:`IB-05`,machineId:y,bulletIds:[`P3.1`],format:`yesno`,difficulty:2,trapPairId:`visual-vs-sql-editor`,stem:`Your team is adopting the visual query editor in Microsoft Fabric. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.visualQuery],statements:[{id:`s1`,text:`The visual query editor is available for warehouses, SQL analytics endpoints, and mirrored databases.`,answer:!0,explain:`Yes. Learn’s article applies to the SQL analytics endpoint, Warehouse, and Mirrored Database.`},{id:`s2`,text:`Visualize results supports queries that include an ORDER BY clause.`,answer:!1,explain:`No. Learn: Visualize results currently doesn’t support SQL queries with an ORDER BY clause.`},{id:`s3`,text:`A user in the workspace Viewer role can move their visual query into the Shared queries folder.`,answer:!1,explain:`No. Viewers and shared recipients can save in My queries but are restricted from moving queries to Shared queries.`}]},{id:`IB-06`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:2,stem:`Without writing SQL, you need to combine a store_sales table in the Sales warehouse with an item table in the Marketing warehouse. Both are in the same workspace. What should you do in the visual query editor?`,sources:[t.visualQuery,t.queryWarehouse],options:[{id:`a`,text:`Create a OneLake shortcut to item inside the Sales warehouse first`,explain:`A shortcut isn’t needed; the editor can query both warehouses once the second is added.`},{id:`b`,text:`Add the Marketing warehouse with + Warehouses, then merge the tables`,explain:`Correct. Learn: add the other warehouse to the Explorer, drag tables from both, and add a merge.`},{id:`c`,text:`Type the three-part name Marketing.dbo.item on the canvas`,explain:`Three-part names are for SQL queries; the visual editor works by dragging tables.`},{id:`d`,text:`Open the OneLake catalog, select the item table, and choose Merge from its menu`,explain:`The OneLake catalog is for discovering items, not building queries.`}],answer:`b`},{id:`IB-07`,machineId:y,bulletIds:[`P3.1`],format:`single`,difficulty:1,trapPairId:`visual-vs-sql-editor`,stem:`A PL-300-trained analyst opens the visual query editor on a Fabric warehouse and finds it familiar. Which experience is the editor based on?`,sources:[t.visualQuery],options:[{id:`a`,text:`DAX query view`,explain:`DAX query view runs DAX against semantic models, not visual steps against a warehouse.`},{id:`b`,text:`The KQL queryset`,explain:`A KQL queryset runs KQL against KQL databases.`},{id:`c`,text:`Power Query diagram view`,explain:`Correct. Learn: the editor uses the Power Query diagram view experience.`},{id:`d`,text:`Data Wrangler`,explain:`Data Wrangler cleans DataFrames inside notebooks.`}],answer:`c`},{id:`IB-08`,machineId:y,bulletIds:[`P3.1`],format:`multi`,difficulty:1,stem:`You ran a visual query on a Fabric warehouse and see the results. Which two actions does the editor offer directly on the results? Choose two.`,sources:[t.visualQuery],options:[{id:`a`,text:`Download Excel file`,explain:`Correct. You can download the results to view them in Excel.`},{id:`b`,text:`Visualize results`,explain:`Correct. Visualize results creates a report on the results.`},{id:`c`,text:`Publish to an eventstream`,explain:`Eventstreams process streaming events; query results aren’t published to them.`},{id:`d`,text:`Export as a Spark DataFrame`,explain:`The results pane doesn’t export Spark DataFrames.`}],answers:[`a`,`b`]},{id:`IB-09`,machineId:y,bulletIds:[`P3.2`],format:`dropdown`,difficulty:2,trapPairId:`sql-vs-kql`,stem:`You need total 2026 revenue per region from a Fabric warehouse, returning only regions above 10,000, highest first. Complete the T-SQL query.`,sources:[t.queryWarehouse,t.groupBy,t.kqlSortOp],language:`tsql`,code:`SELECT Region, SUM(Amount) AS Revenue
FROM dbo.Sales
WHERE OrderDate >= '2026-01-01'
[[1]] Region
[[2]] SUM(Amount) > 10000
[[3]] Revenue DESC;`,slots:[{id:`1`,options:[{id:`a`,text:`PARTITION BY`,explain:`PARTITION BY belongs inside an OVER clause for window functions.`},{id:`b`,text:`GROUP BY`,explain:`Correct. GROUP BY returns one row per region for the SUM.`},{id:`c`,text:`ORDER BY`,explain:`ORDER BY sorts rows; it doesn’t create groups.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`HAVING`,explain:`Correct. HAVING filters groups on an aggregate after grouping.`},{id:`b`,text:`WHERE`,explain:`WHERE filters rows before grouping and can’t use SUM().`},{id:`c`,text:`QUALIFY`,explain:`QUALIFY filters on window function results, not on group aggregates.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`SORT BY`,explain:`sort by is the KQL operator; T-SQL uses ORDER BY.`},{id:`b`,text:`TOP`,explain:`TOP limits the row count and goes after SELECT, not at the end.`},{id:`c`,text:`ORDER BY`,explain:`Correct. ORDER BY Revenue DESC sorts the highest revenue first.`}],answer:`c`}]},{id:`IB-10`,machineId:y,bulletIds:[`P3.2`],format:`single`,difficulty:2,stem:`You run this query in a Fabric warehouse: SELECT Region, Territory, SUM(Sales) AS TotalSales FROM dbo.SalesByTerritory GROUP BY ALL; How are the rows grouped?`,sources:[t.groupBy,t.tsqlSurface],options:[{id:`a`,text:`By Region only, the first column in the SELECT list`,explain:`GROUP BY ALL uses every non-aggregated SELECT expression, not just the first.`},{id:`b`,text:`By every column in the table, even unselected ones`,explain:`Only expressions in the SELECT list are used.`},{id:`c`,text:`By Region and Territory, the non-aggregated columns`,explain:`Correct. In Fabric, GROUP BY ALL groups by all non-aggregated expressions in the SELECT list.`},{id:`d`,text:`Not at all; it returns one grand total row`,explain:`A grand total would need no grouping columns; GROUP BY ALL adds Region and Territory as keys.`}],answer:`c`},{id:`IB-11`,machineId:y,bulletIds:[`P3.2`],format:`single`,difficulty:2,stem:`In the SQL query editor of the SalesWH warehouse, you need to join dbo.Orders to the Customer table of ContosoLakehouse, which is in the same workspace. You already added the lakehouse with + Warehouses. How should you reference the lakehouse table?`,sources:[t.queryWarehouse],options:[{id:`a`,text:`ContosoLakehouse.dbo.Customer`,explain:`Correct. Learn: reference tables in added databases by using three-part naming.`},{id:`b`,text:`OPENROWSET over the lakehouse Files path`,explain:`OPENROWSET reads files; the lakehouse table is reachable directly by name.`},{id:`c`,text:`workspace.ContosoLakehouse.dbo.Customer`,explain:`Cross-database queries in the same workspace use three-part, not four-part, names.`},{id:`d`,text:`dbo.Customer, after a USE ContosoLakehouse statement`,explain:`Switching databases loses the reference to SalesWH’s dbo.Orders in the same query.`}],answer:`a`},{id:`IB-12`,machineId:y,bulletIds:[`P3.2`],format:`yesno`,difficulty:3,preview:!0,stem:`You are writing T-SQL for a Fabric warehouse and its lakehouse’s SQL analytics endpoint. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.tsqlSurface,t.groupBy],statements:[{id:`s1`,text:`Both support GROUP BY ALL and ORDER BY ALL without a column list.`,answer:!0,explain:`Yes. Learn’s T-SQL surface area lists GROUP BY ALL and ORDER BY ALL for both.`},{id:`s2`,text:`Both support FROM-first query syntax as well as SELECT-first syntax.`,answer:!0,explain:`Yes. Learn: Fabric Data Warehouse and the SQL analytics endpoint support SELECT-first and FROM-first syntax.`},{id:`s3`,text:`Nested common table expressions are generally available.`,answer:!1,explain:`No. Standard and sequential CTEs are generally available, but nested CTEs are a preview feature.`}]},{id:`IB-13`,machineId:y,bulletIds:[`P3.2`],format:`single`,difficulty:1,stem:`You open a Fabric warehouse and want a quick look at the first rows of DimCustomer without typing a query. What should you do in the Explorer?`,sources:[t.queryWarehouse],options:[{id:`a`,text:`Select New visual query and add a Keep top rows step`,explain:`That works but needs several steps; the Explorer offers a one-click option.`},{id:`b`,text:`Right-click the table and select Select TOP 100 rows`,explain:`Correct. Learn: right-click the table in the Explorer and select Select TOP 100 rows.`},{id:`c`,text:`Open the table in the OneLake catalog preview`,explain:`The catalog shows item details; the warehouse Explorer is where you preview table rows.`},{id:`d`,text:`Select the table and choose View SQL`,explain:`View SQL belongs to the visual query editor and shows generated SQL.`}],answer:`b`},{id:`IB-14`,machineId:y,bulletIds:[`P3.2`],format:`single`,difficulty:1,stem:`A developer wants to query a Fabric warehouse from SQL Server Management Studio (SSMS) instead of the browser. What do they use to connect?`,sources:[t.queryWarehouse],options:[{id:`a`,text:`The KQL database query URI`,explain:`That URI connects to a KQL database, not a warehouse.`},{id:`b`,text:`The ABFS path of the warehouse folder in OneLake`,explain:`An ABFS path reads files through OneLake APIs, not T-SQL sessions.`},{id:`c`,text:`The warehouse’s T-SQL connection string`,explain:`Correct. Learn: tools such as SSMS connect to a SQL analytics endpoint or warehouse through a T-SQL connection string.`},{id:`d`,text:`The semantic model’s XMLA endpoint`,explain:`XMLA connects tools to semantic models, not warehouses.`}],answer:`c`},{id:`IB-15`,machineId:y,bulletIds:[`P3.2`],format:`multi`,difficulty:2,trapPairId:`endpoint-vs-warehouse`,stem:`You are connected to the SQL analytics endpoint of a lakehouse in the SQL query editor. Which two statements can you run successfully? Choose two.`,sources:[t.endpoint,t.queryWarehouse],options:[{id:`a`,text:`UPDATE dbo.Orders SET Status = 'Closed' WHERE OrderID = 5`,explain:`The endpoint is read-only over Delta tables; you can’t update data through it.`},{id:`b`,text:`INSERT INTO dbo.Orders SELECT * FROM staging_orders`,explain:`Inserting isn’t possible through the endpoint. Use Spark to modify lakehouse data.`},{id:`c`,text:`A CREATE VIEW statement over two lakehouse tables`,explain:`Correct. You can create views, functions, and procedures in the SQL analytics endpoint.`},{id:`d`,text:`A SELECT that joins to another warehouse in the workspace by its three-part name`,explain:`Correct. Cross-database queries work from SQL analytics endpoints and warehouses in the same workspace.`}],answers:[`c`,`d`]},{id:`RB-01`,machineId:b,bulletIds:[`P2.1`],format:`single`,difficulty:2,stem:`Analysts repeatedly query orders for one region at a time from a Fabric warehouse. You need a reusable object that takes the region as a parameter and can be used in the FROM clause of their queries. What should you create?`,sources:[t.createFunction,t.createView,t.cte],options:[{id:`a`,text:`A view with a WHERE clause on Region`,explain:`A view can be used in FROM but can’t take parameters, so the region would be fixed.`},{id:`b`,text:`A stored procedure`,explain:`A procedure can take parameters but can’t be used in the FROM clause of a SELECT.`},{id:`c`,text:`A common table expression`,explain:`A CTE exists only within one statement, so it isn’t reusable.`},{id:`d`,text:`An inline table-valued function`,explain:`Correct. An inline TVF accepts parameters and returns a table defined by a single SELECT.`}],answer:`d`},{id:`RB-02`,machineId:b,bulletIds:[`P2.1`],format:`single`,difficulty:1,stem:`A nightly ETL step inserts rows from staging tables into a warehouse fact table. A pipeline must run the step on a schedule. Where should the T-SQL logic live?`,sources:[t.loadTables,t.createProc],options:[{id:`a`,text:`In a view that selects from the staging tables`,explain:`A view returns data; it can’t insert rows into the fact table.`},{id:`b`,text:`In a stored procedure that the pipeline runs`,explain:`Correct. Learn: pipelines can execute SQL scripts and stored procedures to orchestrate ETL.`},{id:`c`,text:`In an inline table-valued function`,explain:`An inline TVF returns a single SELECT’s result and can’t insert data.`},{id:`d`,text:`In a query saved to the Shared queries folder`,explain:`Saved queries are for people running them in the editor, not for scheduled ETL.`}],answer:`b`},{id:`RB-03`,machineId:b,bulletIds:[`P2.1`],format:`single`,difficulty:2,trapPairId:`endpoint-vs-warehouse`,stem:`You created a stored procedure in the SQL analytics endpoint of a lakehouse. It runs an INSERT into a lakehouse table and fails. You need the load to work. What should you do?`,sources:[t.endpoint,t.warehouse],options:[{id:`a`,text:`Grant the user who runs the procedure the db_owner role on the SQL analytics endpoint`,explain:`Permissions don’t help: the endpoint is read-only for data.`},{id:`b`,text:`Convert the procedure into a view`,explain:`A view can’t insert data either.`},{id:`c`,text:`Load the data with Spark, or move the table and procedure into a warehouse`,explain:`Correct. The endpoint can’t insert, update, or delete. Use Spark to modify lakehouse data, or use a warehouse for T-SQL DML.`},{id:`d`,text:`Wrap the INSERT in an explicit transaction`,explain:`A transaction doesn’t make the read-only endpoint writable.`}],answer:`c`},{id:`RB-04`,machineId:b,bulletIds:[`P2.1`],format:`dropdown`,difficulty:2,stem:`A warehouse customer dimension uses SCD type 2 (IsCurrent) and soft deletes (IsDeleted). You need an object that always returns only current, non-deleted customers for reports. Complete the T-SQL statement.`,sources:[t.createView,t.loadTables],language:`tsql`,code:`CREATE [[1]] dbo.vActiveCustomer AS
SELECT CustomerID, CustomerName, Region
FROM dbo.DimCustomer
WHERE [[2]] [[3]] IsDeleted = 0;`,slots:[{id:`1`,options:[{id:`a`,text:`TABLE`,explain:`CREATE TABLE … AS would copy the rows once; it wouldn’t stay current.`},{id:`b`,text:`PROCEDURE`,explain:`A procedure can’t be queried like a table by reports.`},{id:`c`,text:`VIEW`,explain:`Correct. A view stores the query, so reports always see the current filter result.`}],answer:`c`},{id:`2`,options:[{id:`a`,text:`IsCurrent = 1`,explain:`Correct. The current version row of each member has IsCurrent set to 1.`},{id:`b`,text:`IsCurrent = 0`,explain:`This returns only expired historical versions.`},{id:`c`,text:`IsDeleted = 1`,explain:`This returns soft-deleted members, the opposite of the goal.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`OR`,explain:`OR would return rows meeting either condition, including deleted or expired ones.`},{id:`b`,text:`AND`,explain:`Correct. Both conditions must be true.`},{id:`c`,text:`UNION`,explain:`UNION combines two queries; it isn’t a condition operator.`}],answer:`b`}]},{id:`RB-05`,machineId:b,bulletIds:[`P2.1`],format:`dropdown`,difficulty:3,stem:`You need an inline table-valued function in a Fabric warehouse that returns the sales rows for a region passed as a parameter. Complete the T-SQL statement.`,sources:[t.createFunction],language:`tsql`,code:`CREATE FUNCTION dbo.fnSalesByRegion (@Region varchar(50))
[[1]] TABLE
AS
[[2]] SELECT OrderID, Amount
  FROM dbo.FactSales
  WHERE Region = [[3]];`,slots:[{id:`1`,options:[{id:`a`,text:`RETURN`,explain:`RETURN introduces the SELECT that defines the result, not the return type.`},{id:`b`,text:`OUTPUT`,explain:`OUTPUT marks procedure output parameters; it doesn’t declare a function’s return type.`},{id:`c`,text:`RETURNS`,explain:`Correct. RETURNS TABLE declares an inline table-valued function.`}],answer:`c`},{id:`2`,options:[{id:`a`,text:`RETURN`,explain:`Correct. In an inline TVF, RETURN is followed by the single SELECT that defines the table.`},{id:`b`,text:`BEGIN`,explain:`An inline TVF has no function body block; it returns a single SELECT.`},{id:`c`,text:`EXEC`,explain:`EXEC runs a procedure or command; it doesn’t define a function result.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`'@Region'`,explain:`Quoting the name compares Region to the literal text @Region.`},{id:`b`,text:`@Region`,explain:`Correct. The parameter supplies the region to filter on.`},{id:`c`,text:`Region`,explain:`Comparing the column to itself returns every row with a non-NULL region.`}],answer:`b`}]},{id:`RB-06`,machineId:b,bulletIds:[`P2.1`],format:`yesno`,difficulty:2,trapPairId:`endpoint-vs-warehouse`,stem:`You are planning reusable SQL logic over lakehouse data in Microsoft Fabric. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.endpoint,t.tsqlSurface,t.visualQuery],statements:[{id:`s1`,text:`You can create T-SQL views, functions, and stored procedures in a lakehouse’s SQL analytics endpoint.`,answer:!0,explain:`Yes. Learn: you can create views, functions, and procedures over Delta tables in the SQL analytics endpoint.`},{id:`s2`,text:`Permissions granted on a view in the SQL analytics endpoint also restrict users who read the same Delta tables from Spark.`,answer:!1,explain:`No. SQL security rules on the endpoint apply only when data is accessed through the endpoint, not through Spark or other tools.`},{id:`s3`,text:`The visual query editor can save a query as a view.`,answer:!0,explain:`Yes. Save as view creates a view from the visual query.`}]},{id:`RB-07`,machineId:b,bulletIds:[`P2.1`],format:`single`,difficulty:1,stem:`Your Delta tables live in a Fabric lakehouse. You want to define a T-SQL view over two of them without copying data anywhere. Where should you create the view?`,sources:[t.endpoint,t.tsqlSurface],options:[{id:`a`,text:`In the lakehouse’s SQL analytics endpoint`,explain:`Correct. Learn: you can create T-SQL views on top of lakehouse Delta tables in the SQL analytics endpoint.`},{id:`b`,text:`In the Files section of the lakehouse`,explain:`Files holds unmanaged files; T-SQL objects aren’t created there.`},{id:`c`,text:`In a warehouse, after copying both tables into it`,explain:`Copying isn’t needed; the endpoint can host the view directly.`},{id:`d`,text:`In a KQL queryset attached to the lakehouse`,explain:`KQL querysets run KQL against KQL databases, not T-SQL views.`}],answer:`a`},{id:`RB-08`,machineId:b,bulletIds:[`P2.1`],format:`single`,difficulty:1,stem:`A stored procedure named dbo.LoadDailySales exists in a Fabric warehouse. You need to run it from the SQL query editor. Which statement should you use?`,sources:[t.execute,t.createProc,t.createProc],options:[{id:`a`,text:`SELECT * FROM dbo.LoadDailySales;`,explain:`Learn runs procedures with EXEC (or EXECUTE), not by selecting from them.`},{id:`b`,text:`CALL dbo.LoadDailySales();`,explain:`Learn’s T-SQL statement for running a procedure is EXEC (or EXECUTE).`},{id:`c`,text:`RUN PROCEDURE dbo.LoadDailySales;`,explain:`Learn’s T-SQL statement for running a procedure is EXEC (or EXECUTE).`},{id:`d`,text:`EXEC dbo.LoadDailySales;`,explain:`Correct. EXEC (or EXECUTE) runs a user-defined stored procedure.`}],answer:`d`},{id:`RB-09`,machineId:b,bulletIds:[`P2.1`],format:`match`,difficulty:2,stem:`You are choosing T-SQL objects for a Fabric warehouse. Match each requirement to the object that meets it.`,sources:[t.createView,t.createFunction,t.createProc,t.loadTables],prompts:[{id:`p1`,text:`Hide a three-table join behind a name reports can query like a table, with no parameters`},{id:`p2`,text:`Return a table filtered by a parameter, usable in a FROM clause`},{id:`p3`,text:`Run INSERT and UPDATE statements for an ETL step called by a pipeline`}],choices:[{id:`c1`,text:`View`},{id:`c2`,text:`Inline table-valued function`},{id:`c3`,text:`Stored procedure`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`A view is a virtual table defined by a query.`},{promptId:`p2`,choiceId:`c2`,explain:`An inline TVF accepts parameters and returns a table from a single SELECT.`},{promptId:`p3`,choiceId:`c3`,explain:`Procedures can modify data, and pipelines can run them to orchestrate ETL.`}]},{id:`RB-10`,machineId:b,bulletIds:[`P2.1`],format:`multi`,difficulty:2,stem:`You are writing a SELECT in a Fabric warehouse. Which two kinds of user-defined objects can you reference in its FROM clause? Choose two.`,sources:[t.createView,t.createFunction,t.createProc],options:[{id:`a`,text:`A view`,explain:`Correct. A view behaves like a virtual table.`},{id:`b`,text:`A stored procedure`,explain:`Procedures are run with EXEC; views and table-valued functions are what you query in FROM.`},{id:`c`,text:`An inline table-valued function`,explain:`Correct. A TVF returns a table and is queried in FROM.`},{id:`d`,text:`A pipeline`,explain:`A pipeline is a Data Factory item that orchestrates activities, not a SQL object.`}],answers:[`a`,`c`]}],S=`thread-intake`,C=[{id:`TI-01`,machineId:S,bulletIds:[`P1.1`],format:`single`,difficulty:1,stem:`You need to create a reusable cloud connection to an Azure SQL database so that several Fabric pipelines can use it. Where should you create the connection?`,sources:[t.connections],options:[{id:`a`,text:`Settings > Manage connections and gateways`,explain:`Correct. New cloud connections are created on the Connections tab of Manage connections and gateways.`},{id:`b`,text:`Workspace settings > Azure connections`,explain:`Workspace Azure connections settings don’t define reusable data source connections for pipelines.`},{id:`c`,text:`The lakehouse’s SQL analytics endpoint settings`,explain:`The SQL analytics endpoint is a read-only query surface over Delta tables, not a place to define source connections.`},{id:`d`,text:`The OneLake catalog Govern tab`,explain:`Govern shows governance insights and admin settings; it doesn’t create data source connections.`}],answer:`a`},{id:`TI-02`,machineId:S,bulletIds:[`P1.1`],format:`multi`,difficulty:2,placement:!0,stem:`You are creating a new cloud connection to a SQL Server data source in Manage connections and gateways. Which two authentication methods can you choose for this connection type? Choose two.`,sources:[t.connections],options:[{id:`a`,text:`Workspace identity in the CREDENTIAL clause`,explain:`Workspace identity in CREDENTIAL belongs to the T-SQL COPY statement, not to creating a cloud connection.`},{id:`b`,text:`OAuth2`,explain:`Correct. OAuth2 is listed, with the caveat that long-running queries can fail when the token expires.`},{id:`c`,text:`Row-level security role`,explain:`RLS roles restrict rows in a model or warehouse; they aren’t an authentication method for a connection.`},{id:`d`,text:`Service Principal`,explain:`Correct. Service Principal is one of the listed authentication methods.`}],answers:[`b`,`d`]},{id:`TI-03`,machineId:S,bulletIds:[`P1.1`],format:`single`,difficulty:1,stem:`Your company stores sales data in a SQL Server database in its own datacenter, behind the corporate firewall. You need a Dataflow Gen2 in Fabric to read this data. What should you set up?`,sources:[t.gateway],options:[{id:`a`,text:`A OneLake shortcut to the SQL Server database`,explain:`Shortcuts point to storage locations such as OneLake, ADLS, or S3; they don’t reach an on-premises SQL Server instance.`},{id:`b`,text:`An on-premises data gateway`,explain:`Correct. The on-premises data gateway connects Fabric to data sources inside your network.`},{id:`c`,text:`An eventstream with a custom endpoint`,explain:`Eventstreams ingest streaming events; they aren’t used to query an on-premises relational database for a dataflow.`},{id:`d`,text:`The XMLA endpoint of the workspace`,explain:`The XMLA endpoint exposes semantic models to client tools; it doesn’t connect Fabric to on-premises sources.`}],answer:`b`},{id:`TI-04`,machineId:S,bulletIds:[`P1.1`],format:`yesno`,difficulty:2,stem:`You manage connections for a Fabric tenant. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.connections],statements:[{id:`s1`,text:`Removing a connection from Manage connections and gateways can stop items that depend on it from working.`,answer:!0,explain:`Yes. Learn warns that when you remove a data source, any items that depend on it stop working.`},{id:`s2`,text:`The privacy level set on a cloud connection also applies to DirectQuery connections.`,answer:!1,explain:`No. Learn notes that the privacy level setting doesn’t affect DirectQuery connections.`},{id:`s3`,text:`OAuth2 connections can fail for long-running queries that exceed the token’s lifetime.`,answer:!0,explain:`Yes. Long-running queries might fail if they exceed the OAuth token expiration.`}]},{id:`TI-05`,machineId:S,bulletIds:[`P1.1`],format:`single`,difficulty:2,stem:`A developer wants to check whether a specific SaaS source can be used as a destination as well as a source before choosing an ingestion tool. Which Learn resource lists, per connector, whether Dataflow Gen2, the pipeline Copy activity, and Copy job support it as a source or destination?`,sources:[t.connectors],options:[{id:`a`,text:`The T-SQL surface area article for Fabric Data Warehouse`,explain:`That article lists supported T-SQL syntax, not connector capabilities.`},{id:`b`,text:`The Microsoft Fabric decision guide for choosing a data store`,explain:`That guide compares lakehouse, warehouse, eventhouse, and databases, not connectors.`},{id:`c`,text:`The Data Factory connector overview`,explain:`Correct. The connector overview table shows source/destination support for Dataflow Gen2, pipelines, and Copy job per connector.`},{id:`d`,text:`The OneLake shortcuts article`,explain:`The shortcuts article lists shortcut targets (OneLake, ADLS, S3, and so on), not Data Factory connectors.`}],answer:`c`},{id:`TI-06`,machineId:S,bulletIds:[`P1.1`],format:`single`,difficulty:2,stem:`You created a cloud connection in Manage connections and gateways. A colleague now needs a connection to the same source for a semantic model. According to Learn, how do cloud connections for semantic models and dataflows get created today?`,sources:[t.connections],options:[{id:`a`,text:`Through Power Query Online’s Get data experience`,explain:`Correct. Learn notes that cloud connections currently work with pipelines and Kusto, and that semantic models and dataflows use Power Query Online’s Get data experience to create personal cloud connections.`},{id:`b`,text:`By creating a OneLake shortcut in the workspace`,explain:`A shortcut references storage; it isn’t how a semantic model’s connection is defined.`},{id:`c`,text:`By enabling XMLA read-write on the capacity`,explain:`XMLA read-write governs tool access to semantic models, not how their source connections are created.`},{id:`d`,text:`By assigning the colleague the Member workspace role`,explain:`A workspace role grants permissions on items; it doesn’t create a data source connection.`}],answer:`a`},{id:`TI-07`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`shortcut-mirror-copy`,stem:`Another team stores curated Delta tables in an ADLS Gen2 account. You need your lakehouse to query those tables without copying the data, and changes at the source must be visible immediately. What should you create?`,sources:[t.shortcuts,t.onelake],options:[{id:`a`,text:`A Copy job that runs every 15 minutes`,explain:`A Copy job makes a physical copy on a schedule, so it duplicates data and isn’t immediate.`},{id:`b`,text:`A mirrored database`,explain:`Mirroring replicates operational databases into OneLake; it isn’t used to reference Delta files already in ADLS.`},{id:`c`,text:`A OneLake shortcut in the Tables folder`,explain:`Correct. A shortcut references the data in place without copying, and source changes are visible immediately.`},{id:`d`,text:`A Dataflow Gen2 with a lakehouse destination`,explain:`A dataflow copies data into the destination when it runs, which duplicates the data.`}],answer:`c`},{id:`TI-08`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`shortcut-mirror-copy`,stem:`Your company runs an operational Azure SQL Database. Analysts need near real-time copies of its tables in OneLake for reporting, with minimal setup and no pipelines to build or maintain. What should you use?`,sources:[t.mirroring,t.movement],options:[{id:`a`,text:`A pipeline with a Copy activity on a schedule`,explain:`A scheduled Copy activity works but needs you to build and manage the pipeline and incremental state yourself.`},{id:`b`,text:`Mirroring`,explain:`Correct. Mirroring continuously replicates the database into OneLake as Delta tables with minimal setup and no pipelines.`},{id:`c`,text:`A notebook that reads the database with JDBC`,explain:`A notebook is custom code you must schedule and maintain, which is the opposite of minimal setup.`},{id:`d`,text:`An eventstream`,explain:`Eventstreams are for streaming events, not for replicating a relational database’s tables.`}],answer:`b`},{id:`TI-09`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`shortcut-mirror-copy`,stem:`You are ingesting raw (bronze) data from many sources into Fabric. You need incremental copies and change data capture without building pipelines, and you want more control than mirroring offers. Which data movement option does Learn recommend?`,sources:[t.movement,t.dataFactory],options:[{id:`a`,text:`Copy job`,explain:`Correct. Learn recommends starting with Copy job for bronze ingestion; it supports bulk, incremental, and CDC copy without pipelines.`},{id:`b`,text:`Mirroring`,explain:`Mirroring is the simple choice for replicating curated data with fixed behavior; it offers less control than Copy job.`},{id:`c`,text:`Eventstreams`,explain:`Eventstreams are for real-time streaming events, not batch ingestion from many sources.`},{id:`d`,text:`A OneLake shortcut`,explain:`A shortcut references data without copying it, so it doesn’t provide incremental copies or CDC.`}],answer:`a`},{id:`TI-10`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,stem:`In a notebook, df holds data read from a Parquet file in the Files area of the default lakehouse. You need to save it as a new Delta table named sales in the Tables section, replacing any existing data. Which line should you run?`,sources:[t.notebookLoad],options:[{id:`a`,text:`df.write.mode("overwrite").format("delta").saveAsTable("sales")`,explain:`Correct. Learn’s example writes a Delta table to the Tables section with saveAsTable; overwrite replaces existing data.`},{id:`b`,text:`df.write.mode("append").format("delta").saveAsTable("sales")`,explain:`append adds rows to an existing table instead of replacing its data.`},{id:`c`,text:`df.write.mode("overwrite").format("csv").save("Files/sales")`,explain:`This writes CSV files to the Files area, not a Delta table in the Tables section.`},{id:`d`,text:`df.write.mode("overwrite").format("parquet").save("Files/sales")`,explain:`This writes Parquet files to the Files area; it doesn’t create a Delta table.`}],answer:`a`},{id:`TI-11`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,stem:`You need to load about 1.5 billion rows from Parquet files in an Azure storage account into a Fabric warehouse table as part of a T-SQL script, with the highest ingestion throughput. What should you use?`,sources:[t.ingestWarehouse,t.copyInto],options:[{id:`a`,text:`INSERT ... SELECT from OPENROWSET`,explain:`OPENROWSET can read the files, but Learn notes it can be slower than loading; COPY is the high-throughput statement.`},{id:`b`,text:`A Dataflow Gen2`,explain:`Dataflow Gen2 is a low-code option for smaller data with transformations, not the highest-throughput T-SQL load.`},{id:`c`,text:`Batches of INSERT … VALUES statements`,explain:`INSERT … VALUES adds literal rows supplied in the script, which isn’t a way to load billions of rows from files; Learn names COPY as the highest-throughput option.`},{id:`d`,text:`The COPY statement (COPY INTO)`,explain:`Correct. COPY provides the highest ingestion throughput and runs inside T-SQL.`}],answer:`d`},{id:`TI-12`,machineId:S,bulletIds:[`P1.3`],format:`dropdown`,difficulty:2,placement:!0,stem:`You need to bulk-load Parquet files from an Azure Blob Storage container into the existing warehouse table dbo.Trips. Complete the T-SQL statement.`,sources:[t.copyInto],language:`tsql`,code:`[[1]] dbo.Trips
FROM 'https://<account>.blob.core.windows.net/<container>/trips/'
WITH ([[2]] = 'PARQUET');`,slots:[{id:`1`,options:[{id:`a`,text:`COPY INTO`,explain:`Correct. COPY INTO loads files from Azure storage into a warehouse table.`},{id:`b`,text:`INSERT INTO`,explain:`INSERT INTO needs a VALUES list or SELECT, not a file URL with WITH options.`},{id:`c`,text:`MERGE INTO`,explain:`MERGE synchronizes a target with a source table; it doesn’t read files from a URL.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`DATA_SOURCE`,explain:`DATA_SOURCE isn’t the COPY option that declares the file format.`},{id:`b`,text:`FORMAT_TYPE`,explain:`FORMAT_TYPE isn’t the COPY argument used in Learn’s example.`},{id:`c`,text:`FILE_TYPE`,explain:`Correct. Learn’s Parquet example specifies only FILE_TYPE = 'PARQUET'.`}],answer:`c`}]},{id:`TI-13`,machineId:S,bulletIds:[`P1.3`],format:`yesno`,difficulty:3,placement:!0,stem:`You are adding OneLake shortcuts to a lakehouse that doesn’t use schemas. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.shortcuts],statements:[{id:`s1`,text:`You can create a shortcut in a subfolder of the Tables folder, for example Tables/finance/budget.`,answer:!1,explain:`No. In the Tables folder, shortcuts can only be created at the top level.`},{id:`s2`,text:`Deleting a shortcut also deletes the data at its target.`,answer:!1,explain:`No. Shortcuts behave like symbolic links; deleting one leaves the target unaffected.`},{id:`s3`,text:`A shortcut named "sales orders" (with a space) is recognized as a Delta table in the Tables folder.`,answer:!1,explain:`No. Delta doesn’t support spaces in table names, so OneLake doesn’t recognize such a shortcut as a table.`}]},{id:`TI-14`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:3,stem:`A data engineer used Spark to write a Delta table to an external location outside the lakehouse’s Tables area. Analysts can’t see the table in the lakehouse’s SQL analytics endpoint. You need the table to appear there without copying it. What should you do?`,sources:[t.loadLakehouse,t.endpoint],options:[{id:`a`,text:`Grant the analysts ReadData on the lakehouse`,explain:`Permissions don’t make an external table visible; external Delta tables written by Spark aren’t surfaced by the endpoint at all.`},{id:`b`,text:`Create a shortcut to the table in the Tables section`,explain:`Correct. Learn says to use shortcuts in the Tables section to make external Delta tables visible to the SQL analytics endpoint.`},{id:`c`,text:`Refresh the SQL analytics endpoint metadata`,explain:`Metadata sync only picks up tables in the lakehouse’s Tables area; it won’t surface an external location.`},{id:`d`,text:`Move the table into the Files folder`,explain:`Tables in the Files folder aren’t exposed by the SQL analytics endpoint either.`}],answer:`b`},{id:`TI-15`,machineId:S,bulletIds:[`P1.3`],format:`match`,difficulty:2,placement:!0,trapPairId:`dataflow-pipeline-notebook`,stem:`You are choosing how to get data into a lakehouse for four scenarios. Match each scenario to the approach Learn recommends.`,sources:[t.loadLakehouse],prompts:[{id:`p1`,text:`A few small CSV files on your laptop, no transformation`},{id:`p2`,text:`Small to medium data that needs visual, low-code transformations`},{id:`p3`,text:`Large volumes copied on a schedule and chained with other activities`},{id:`p4`,text:`Complex transformation logic or a source the other tools don’t support`}],choices:[{id:`c1`,text:`Upload files in Lakehouse explorer`},{id:`c2`,text:`Dataflow Gen2`},{id:`c3`,text:`Pipeline with a Copy activity`},{id:`c4`,text:`Notebook code`},{id:`c5`,text:`Eventstream`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Uploading through Lakehouse explorer suits small local files with no transformation.`},{promptId:`p2`,choiceId:`c2`,explain:`Dataflow Gen2 is the low-code, visual option for small to medium data.`},{promptId:`p3`,choiceId:`c3`,explain:`Pipelines provide scalable copy, scheduling, triggers, and chained activities. Eventstream (unused) is for real-time events.`},{promptId:`p4`,choiceId:`c4`,explain:`Notebook code is the most flexible option for complex logic or unsupported sources.`}]},{id:`TI-16`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:2,placement:!0,stem:`A notebook attached to lakehouse LH_Sales needs to read a Parquet file stored in a different lakehouse, LH_Marketing, in the same workspace. What path should the Spark code use?`,sources:[t.notebookLoad],options:[{id:`a`,text:`A relative path such as Files/sample.parquet`,explain:`Relative paths resolve against the notebook’s default lakehouse (LH_Sales), not LH_Marketing.`},{id:`b`,text:`The /lakehouse/default/Files mount path`,explain:`The default mount points to the notebook’s default lakehouse only.`},{id:`c`,text:`The file’s ABFS path (abfss://…)`,explain:`Correct. Learn says to use the absolute ABFS path when the data is in a different lakehouse.`},{id:`d`,text:`A three-part name such as LH_Marketing.dbo.sample`,explain:`Three-part names are T-SQL cross-database references, not Spark file paths.`}],answer:`c`},{id:`TI-17`,machineId:S,bulletIds:[`P1.3`],format:`multi`,difficulty:2,stem:`You need to load data into a Fabric warehouse from a table in a lakehouse in the same workspace, using only T-SQL. Which two statements can you use? Choose two.`,sources:[t.ingestWarehouse],options:[{id:`a`,text:`CREATE TABLE AS SELECT (CTAS)`,explain:`Correct. CTAS can read from lakehouse tables in the same workspace using three-part names.`},{id:`b`,text:`CREATE EXTERNAL TABLE`,explain:`Learn’s ingestion options for the warehouse list COPY, INSERT...SELECT, SELECT INTO, and CTAS, not external tables.`},{id:`c`,text:`BACKUP DATABASE`,explain:`Backup isn’t a data ingestion statement in Fabric Data Warehouse.`},{id:`d`,text:`INSERT ... SELECT`,explain:`Correct. INSERT...SELECT reads from other warehouses, lakehouses, or mirrored databases in the same workspace.`}],answers:[`a`,`d`]},{id:`TI-18`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:1,trapPairId:`shortcut-mirror-copy`,stem:`You set up mirroring for an operational database. Which item does mirroring create in your workspace so analysts can query the replicated tables with T-SQL?`,sources:[t.mirroring],options:[{id:`a`,text:`A Dataflow Gen2`,explain:`Mirroring doesn’t create dataflows; it runs a managed replication process.`},{id:`b`,text:`A warehouse`,explain:`Mirroring doesn’t create a read-write warehouse; it creates a read-only query surface.`},{id:`c`,text:`A KQL database`,explain:`KQL databases live in eventhouses; mirroring lands Delta tables queried with T-SQL.`},{id:`d`,text:`A SQL analytics endpoint`,explain:`Correct. Mirroring creates the replication process plus a SQL analytics endpoint over the replicated Delta tables.`}],answer:`d`},{id:`TI-19`,machineId:S,bulletIds:[`P1.3`],format:`single`,difficulty:3,placement:!0,stem:`You use the T-SQL COPY statement to load files from OneLake into a warehouse. Security requires that COPY authenticate to the source as the Fabric workspace’s identity rather than with a key or SAS token. What should you specify?`,sources:[t.ingestWarehouse],options:[{id:`a`,text:`CREDENTIAL = (IDENTITY = 'Workspace Identity')`,explain:`Correct. Learn: specify Workspace Identity in the CREDENTIAL clause to impersonate the workspace identity when accessing the source.`},{id:`b`,text:`EXECUTE AS OWNER`,explain:`EXECUTE AS changes the execution context of modules; it doesn’t set COPY’s source credential.`},{id:`c`,text:`A Service Principal connection in Manage connections and gateways`,explain:`Cloud connections are used by pipelines and Kusto; COPY uses its own CREDENTIAL clause.`},{id:`d`,text:`A OneLake security role with ReadWrite`,explain:`OneLake security roles govern data-plane access for users; they don’t set how COPY authenticates.`}],answer:`a`},{id:`TI-20`,machineId:S,bulletIds:[`P1.3`],format:`order`,difficulty:2,stem:`You need to load Parquet files into a new warehouse table with the COPY statement and confirm the result. Put the steps in order.`,sources:[t.copyInto],items:[{id:`i1`,text:`Run SELECT COUNT_BIG(*) against the table`,explain:`Last: count the rows to confirm the load.`},{id:`i2`,text:`Run COPY INTO with the source URL and FILE_TYPE`,explain:`Second: COPY loads the files into the existing table.`},{id:`i3`,text:`Create the destination table with CREATE TABLE`,explain:`First: COPY needs the destination table to exist.`}],answerOrder:[`i3`,`i2`,`i1`]}],w=`carding-machine`,T=`twisting-frame`,E=[{id:`CM-01`,machineId:w,bulletIds:[`P2.7`],format:`single`,difficulty:2,placement:!0,trapPairId:`where-having-qualify`,stem:`A warehouse staging table has several rows per CustomerID, each with a different ModifiedAt value. You need to keep only the most recent row for each customer, in a single SELECT, without a subquery. Which clause should you add?`,sources:[t.qualify],options:[{id:`a`,text:`QUALIFY ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY ModifiedAt DESC) = 1`,explain:`Correct. QUALIFY filters on the window function result after it is computed, keeping row 1 (the newest) per customer.`},{id:`b`,text:`WHERE ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY ModifiedAt DESC) = 1`,explain:`WHERE runs before window functions are computed, so it can’t filter on ROW_NUMBER().`},{id:`c`,text:`GROUP BY CustomerID HAVING COUNT(*) = 1`,explain:`This keeps only customers that have exactly one row and drops every customer with duplicates.`},{id:`d`,text:`SELECT DISTINCT on all columns`,explain:`Rows that differ in ModifiedAt aren’t identical, so DISTINCT keeps all of them.`}],answer:`a`},{id:`CM-02`,machineId:w,bulletIds:[`P2.7`],format:`dropdown`,difficulty:2,placement:!0,stem:`You need to return one row per OrderID from a warehouse table, keeping the row with the latest LoadDate. Complete the T-SQL query.`,sources:[t.qualify,t.overClause],language:`tsql`,code:`SELECT OrderID, Amount, LoadDate
FROM staging.Orders
[[1]] ROW_NUMBER() OVER ([[2]] OrderID ORDER BY LoadDate [[3]]) = 1;`,slots:[{id:`1`,options:[{id:`a`,text:`QUALIFY`,explain:`Correct. QUALIFY filters on window function results.`},{id:`b`,text:`HAVING`,explain:`HAVING filters grouped results after GROUP BY, not window function results.`},{id:`c`,text:`WHERE`,explain:`WHERE runs before window functions, so it can’t use ROW_NUMBER().`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`GROUP BY`,explain:`GROUP BY isn’t valid inside an OVER clause.`},{id:`b`,text:`PARTITION BY`,explain:`Correct. PARTITION BY restarts numbering for each OrderID.`},{id:`c`,text:`ORDER BY`,explain:`ORDER BY sets the numbering order; the grouping into OrderID sets comes from PARTITION BY.`}],answer:`b`},{id:`3`,options:[{id:`a`,text:`ASC`,explain:`Ascending would number the oldest LoadDate as 1.`},{id:`b`,text:`NULLS LAST`,explain:`This isn’t the sort direction that puts the latest row first.`},{id:`c`,text:`DESC`,explain:`Correct. Descending puts the latest LoadDate first, so row 1 is the newest.`}],answer:`c`}]},{id:`CM-03`,machineId:w,bulletIds:[`P2.7`],format:`single`,difficulty:1,placement:!0,stem:`While loading a warehouse dimension, you need to replace NULL values in the Region column with the text Unknown. Which T-SQL expression should you use?`,sources:[t.coalesce,t.nullif,t.concat],options:[{id:`a`,text:`TRY_CAST(Region AS varchar(50))`,explain:`TRY_CAST converts types and returns NULL on failure; it doesn’t replace NULLs.`},{id:`b`,text:`COALESCE(Region, 'Unknown')`,explain:`Correct. COALESCE returns the first non-NULL argument, so NULL regions become Unknown.`},{id:`c`,text:`NULLIF(Region, 'Unknown')`,explain:`NULLIF returns NULL when the two values are equal; it creates NULLs rather than replacing them.`},{id:`d`,text:`CONCAT(Region, 'Unknown')`,explain:`CONCAT appends text to every value, which would corrupt the non-NULL regions.`}],answer:`b`},{id:`CM-04`,machineId:w,bulletIds:[`P2.7`],format:`single`,difficulty:1,placement:!0,stem:`You are cleaning a DataFrame in a Fabric notebook with Data Wrangler. You need to remove rows that repeat the same values in the OrderID and LineNumber columns. Which Data Wrangler operation should you apply?`,sources:[t.dataWrangler],options:[{id:`a`,text:`Drop missing values`,explain:`This removes rows with missing values, not duplicate rows.`},{id:`b`,text:`Fill missing values`,explain:`This replaces missing cells with a value; it doesn’t remove duplicates.`},{id:`c`,text:`Drop duplicate rows`,explain:`Correct. It drops rows that have duplicate values in one or more chosen columns.`},{id:`d`,text:`Group by column and aggregate`,explain:`Grouping changes the grain and aggregates values; it isn’t the duplicate-removal operation.`}],answer:`c`},{id:`CM-05`,machineId:w,bulletIds:[`P2.7`],format:`yesno`,difficulty:2,stem:`You are designing the cleaning stage of a warehouse ETL process. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.loadTables,t.dataWrangler],statements:[{id:`s1`,text:`Staging tables should be made available to business users so they can validate raw data.`,answer:!1,explain:`No. Learn: data in staging tables should never be made available to business users.`},{id:`s2`,text:`When a fact row’s dimension lookup fails, Learn suggests storing a special dimension member such as Unknown so the row can still be inserted.`,answer:!0,explain:`Yes. The fact row must still be inserted with a valid key; an Unknown member is one approach.`},{id:`s3`,text:`Data Wrangler can export the cleaning steps it generates back into the notebook as code.`,answer:!0,explain:`Yes. You can copy the code or export it to the notebook as a function.`}]},{id:`CM-06`,machineId:w,bulletIds:[`P2.7`],format:`single`,difficulty:2,placement:!0,stem:`During a fact load, some sales rows reference a ProductCode that doesn’t exist yet in the product dimension. The business doesn’t want to lose these sales. What should the ETL process do, according to Learn?`,sources:[t.loadTables,t.dimTables],options:[{id:`a`,text:`Skip the rows for now and load them on the next run, after the product arrives`,explain:`Learn says the fact row must still be inserted, not skipped.`},{id:`b`,text:`Insert the rows with a NULL product key`,explain:`Learn says a valid dimension key must still be stored.`},{id:`c`,text:`Truncate and reload the product dimension`,explain:`Truncating a dimension with generated surrogate keys invalidates existing fact references.`},{id:`d`,text:`Insert the rows with the key of a special Unknown product member`,explain:`Correct. Store a special member (like Unknown) and update the key later when it’s known.`}],answer:`d`},{id:`CM-07`,machineId:w,bulletIds:[`P2.7`],format:`multi`,difficulty:1,stem:`A DataFrame in a Fabric notebook has empty cells in the Discount column. Using Data Wrangler, which two operations can deal with the missing values? Choose two.`,sources:[t.dataWrangler],options:[{id:`a`,text:`One-hot encode`,explain:`One-hot encoding creates indicator columns per category; it doesn’t handle missing values.`},{id:`b`,text:`Drop missing values`,explain:`Correct. It removes rows that have missing values.`},{id:`c`,text:`Fill missing values`,explain:`Correct. It replaces missing cells with a value you choose.`},{id:`d`,text:`Scale min/max values`,explain:`Scaling rescales numeric values; it doesn’t fill or remove missing ones.`}],answers:[`b`,`c`]},{id:`CM-08`,machineId:w,bulletIds:[`P2.7`],format:`single`,difficulty:1,stem:`Your lakehouse follows the medallion architecture. In which layer should you fix errors, standardize formats, and remove duplicates?`,sources:[t.medallion],options:[{id:`a`,text:`Bronze`,explain:`Bronze stores everything exactly as it arrives; no changes are allowed there.`},{id:`b`,text:`Gold`,explain:`Gold organizes curated data for reports and dashboards, after cleaning.`},{id:`c`,text:`Silver`,explain:`Correct. Silver (enriched) is where you fix errors, standardize formats, and remove duplicates.`},{id:`d`,text:`Staging`,explain:`Staging tables support a warehouse ETL process; they aren’t one of the three medallion layers.`}],answer:`c`},{id:`CM-09`,machineId:w,bulletIds:[`P2.8`],format:`single`,difficulty:2,placement:!0,stem:`You are creating a warehouse table for customer names that include accented and non-Latin characters. Which data type should you use for the name column?`,sources:[t.dataTypes],options:[{id:`a`,text:`varchar`,explain:`Correct. nchar and nvarchar aren’t supported in warehouse tables; Learn says to use char and varchar (UTF-8 collation) instead.`},{id:`b`,text:`nvarchar`,explain:`nvarchar isn’t supported for persisted warehouse table columns.`},{id:`c`,text:`ntext`,explain:`text and ntext aren’t supported; the alternative is varchar.`},{id:`d`,text:`nchar`,explain:`nchar isn’t supported in warehouse tables; use char instead.`}],answer:`a`},{id:`CM-10`,machineId:w,bulletIds:[`P2.8`],format:`match`,difficulty:2,placement:!0,stem:`You are migrating table definitions from SQL Server to a Fabric warehouse. Some source types aren’t supported in warehouse tables. Match each source type to the alternative Learn recommends.`,sources:[t.dataTypes],prompts:[{id:`p1`,text:`money`},{id:`p2`,text:`datetime`},{id:`p3`,text:`tinyint`},{id:`p4`,text:`image`}],choices:[{id:`c1`,text:`decimal`},{id:`c2`,text:`datetime2`},{id:`c3`,text:`smallint`},{id:`c4`,text:`varbinary`},{id:`c5`,text:`float`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`money → decimal (which can’t store the monetary unit).`},{promptId:`p2`,choiceId:`c2`,explain:`datetime and smalldatetime → datetime2.`},{promptId:`p3`,choiceId:`c3`,explain:`tinyint → smallint.`},{promptId:`p4`,choiceId:`c4`,explain:`image → varbinary. float (unused) isn’t Learn’s alternative for any of these.`}]},{id:`CM-11`,machineId:w,bulletIds:[`P2.8`],format:`single`,difficulty:2,placement:!0,stem:`A staging column stores order dates as text, and some values are invalid. You need to convert the column to date in a warehouse query so that invalid values become NULL instead of failing the query. Which function should you use?`,sources:[t.tryCast,t.castConvert,t.formatFn],options:[{id:`a`,text:`CAST(OrderDateText AS date)`,explain:`CAST raises an error when a value can’t be converted, failing the query.`},{id:`b`,text:`COALESCE(OrderDateText, GETDATE())`,explain:`COALESCE replaces NULLs; it doesn’t convert text to date safely.`},{id:`c`,text:`TRY_CAST(OrderDateText AS date)`,explain:`Correct. TRY_CAST returns the converted value, or NULL if the conversion fails.`},{id:`d`,text:`FORMAT(OrderDateText, 'yyyy-MM-dd')`,explain:`FORMAT produces formatted text; it doesn’t return a date type.`}],answer:`c`},{id:`CM-12`,machineId:w,bulletIds:[`P2.8`],format:`yesno`,difficulty:3,stem:`You are designing column types for a Fabric warehouse. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.dataTypes,t.tsqlSurface],statements:[{id:`s1`,text:`datetime2 columns in a warehouse table store at most 6 digits of fractional-second precision.`,answer:!0,explain:`Yes. datetime2 and time are limited to 6 digits of fractional-second precision.`},{id:`s2`,text:`A uniqueidentifier column stored in the warehouse is read as a GUID through a lakehouse’s SQL analytics endpoint.`,answer:!1,explain:`No. It’s stored as binary; the SQL analytics endpoint can’t read the values as uniqueidentifier.`},{id:`s3`,text:`You can use ALTER TABLE to add a nullable column of a supported type to an existing warehouse table.`,answer:!0,explain:`Yes. ADD of nullable columns of supported types is a supported ALTER TABLE operation.`}]},{id:`CM-13`,machineId:w,bulletIds:[`P2.8`],format:`single`,difficulty:1,stem:`In a Fabric notebook, a numeric column was loaded as text, so Data Wrangler shows no histogram for it. Which Data Wrangler operation fixes this?`,sources:[t.dataWrangler],options:[{id:`a`,text:`Change column type`,explain:`Correct. It changes the column’s data type; numeric statistics and histograms appear once the column is numeric.`},{id:`b`,text:`Find and replace`,explain:`Find and replace changes cell contents, not the column’s type.`},{id:`c`,text:`Strip whitespace`,explain:`Stripping whitespace cleans text but leaves the column as text.`},{id:`d`,text:`Split text`,explain:`Split text creates several columns from a delimiter; it doesn’t change the type.`}],answer:`a`},{id:`CM-14`,machineId:w,bulletIds:[`P2.8`],format:`single`,difficulty:3,placement:!0,stem:`A warehouse table stores CustomerGuid as uniqueidentifier. A cross-database query joins it to a lakehouse table through the lakehouse’s SQL analytics endpoint on the same GUID, and returns no matches. What is the cause?`,sources:[t.dataTypes],options:[{id:`a`,text:`Cross-database queries can’t join a warehouse to a lakehouse`,explain:`Warehouses can query lakehouse tables in the same workspace with three-part names.`},{id:`b`,text:`The SQL analytics endpoint reads uniqueidentifier values as binary`,explain:`Correct. uniqueidentifier has no Delta type and is stored as binary, so joins between a warehouse and an endpoint on it don’t work as expected.`},{id:`c`,text:`The lakehouse table needs a primary key constraint`,explain:`Constraints don’t affect how the GUID values are read.`},{id:`d`,text:`The warehouse must use nvarchar for GUIDs`,explain:`nvarchar isn’t supported in warehouse tables.`}],answer:`b`},{id:`CM-15`,machineId:w,bulletIds:[`P2.9`],format:`single`,difficulty:1,placement:!0,trapPairId:`where-having-qualify`,stem:`You are writing the SELECT that loads a warehouse fact table from staging. You need to exclude rows that have no CustomerID before any grouping or window function runs. Where should the condition go?`,sources:[t.qualify],options:[{id:`a`,text:`In a HAVING clause`,explain:`HAVING filters groups after GROUP BY, not individual rows before grouping.`},{id:`b`,text:`In a QUALIFY clause`,explain:`QUALIFY filters after window functions are computed, which is later than required.`},{id:`c`,text:`In the ORDER BY clause`,explain:`ORDER BY sorts results; it doesn’t filter rows.`},{id:`d`,text:`In a WHERE clause`,explain:`Correct. WHERE filters individual rows before grouping and before window functions.`}],answer:`d`},{id:`CM-16`,machineId:w,bulletIds:[`P2.9`],format:`single`,difficulty:2,trapPairId:`where-having-qualify`,stem:`A warehouse query groups sales by region with SUM(Amount). You need to return only the regions whose total exceeds 10,000. Which clause should contain the condition?`,sources:[t.qualify],options:[{id:`a`,text:`HAVING`,explain:`Correct. HAVING filters grouped results after GROUP BY aggregates are computed.`},{id:`b`,text:`WHERE`,explain:`WHERE runs before grouping, so the total doesn’t exist yet.`},{id:`c`,text:`QUALIFY`,explain:`QUALIFY is for filtering on window function results, not on GROUP BY aggregates.`},{id:`d`,text:`PARTITION BY`,explain:`PARTITION BY divides rows for a window function; it doesn’t filter.`}],answer:`a`},{id:`CM-17`,machineId:w,bulletIds:[`P2.9`],format:`order`,difficulty:3,trapPairId:`where-having-qualify`,stem:`A Fabric warehouse query uses WHERE, GROUP BY, HAVING, a window function in the SELECT list, and QUALIFY. Put the clauses in the order they are evaluated.`,sources:[t.qualify],items:[{id:`i1`,text:`QUALIFY`,explain:`QUALIFY is evaluated after window functions are computed (and before ORDER BY).`},{id:`i2`,text:`WHERE`,explain:`WHERE filters rows right after FROM.`},{id:`i3`,text:`HAVING`,explain:`HAVING filters groups after GROUP BY.`},{id:`i4`,text:`GROUP BY`,explain:`GROUP BY follows WHERE.`},{id:`i5`,text:`Window functions are computed`,explain:`Window functions are computed after HAVING.`}],answerOrder:[`i2`,`i4`,`i3`,`i5`,`i1`]},{id:`CM-18`,machineId:w,bulletIds:[`P2.9`],format:`single`,difficulty:1,stem:`You are exploring a pandas DataFrame in a Fabric notebook with Data Wrangler. You need to keep only rows where Country equals Canada. Which operation should you apply?`,sources:[t.dataWrangler],options:[{id:`a`,text:`Select column`,explain:`Select column keeps chosen columns, not rows.`},{id:`b`,text:`Filter`,explain:`Correct. Filter keeps rows that match one or more conditions.`},{id:`c`,text:`Sort`,explain:`Sort orders rows; it doesn’t remove any.`},{id:`d`,text:`Drop column`,explain:`Drop column removes columns, not rows.`}],answer:`b`},{id:`CM-19`,machineId:w,bulletIds:[`P2.9`],format:`dropdown`,difficulty:2,placement:!0,trapPairId:`where-having-qualify`,stem:`You need the regions with more than 100 orders in 2026 from a warehouse table, plus each region’s rank by order count. Complete the T-SQL query.`,sources:[t.qualify],language:`tsql`,code:`SELECT Region, COUNT(*) AS Orders,
       RANK() OVER (ORDER BY COUNT(*) DESC) AS RegionRank
FROM dbo.Orders
[[1]] OrderDate >= '2026-01-01'
GROUP BY Region
[[2]] COUNT(*) > 100;`,slots:[{id:`1`,options:[{id:`a`,text:`HAVING`,explain:`HAVING can’t come before GROUP BY; row filters go in WHERE.`},{id:`b`,text:`WHERE`,explain:`Correct. WHERE filters individual rows (2026 orders) before grouping.`},{id:`c`,text:`QUALIFY`,explain:`QUALIFY filters on window results and comes after HAVING, not before GROUP BY.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`HAVING`,explain:`Correct. HAVING filters the grouped regions on COUNT(*).`},{id:`b`,text:`WHERE`,explain:`A second WHERE after GROUP BY isn’t valid, and WHERE can’t use aggregates.`},{id:`c`,text:`QUALIFY`,explain:`QUALIFY is for window function filters; the condition is on a GROUP BY aggregate.`}],answer:`a`}]},{id:`CM-20`,machineId:w,bulletIds:[`P2.9`],format:`single`,difficulty:2,placement:!0,stem:`In a warehouse, you need to return the single most expensive product in each color, filtering on a window function result without writing a CTE. Which clause makes this possible?`,sources:[t.qualify,t.whereClause],options:[{id:`a`,text:`HAVING MAX(Price)`,explain:`HAVING filters groups, and would return the max price per group rather than the full product row.`},{id:`b`,text:`GROUP BY Color, Product`,explain:`Grouping by color and product returns every product, not the top-priced one per color.`},{id:`c`,text:`QUALIFY ROW_NUMBER() OVER (PARTITION BY Color ORDER BY Price DESC) = 1`,explain:`Correct. Learn’s own example uses QUALIFY with ROW_NUMBER to return the top-priced product per color.`},{id:`d`,text:`WHERE Price = MAX(Price)`,explain:`Aggregates can’t be used in WHERE.`}],answer:`c`},{id:`TF-01`,machineId:T,bulletIds:[`P2.6`],format:`single`,difficulty:1,placement:!0,stem:`An analyst uses the visual query editor on a Fabric warehouse to combine DimCity and FactSale on CityKey, without writing SQL. Which action should they use?`,sources:[t.visualQuery],options:[{id:`a`,text:`Merge queries as new, with CityKey as the common key`,explain:`Correct. Learn’s example merges the two tables with Merge queries as new and picks the key and join kind.`},{id:`b`,text:`Save as table`,explain:`Save as table writes results to a table; it doesn’t combine two tables.`},{id:`c`,text:`View SQL`,explain:`View SQL shows the generated T-SQL; it doesn’t perform the join.`},{id:`d`,text:`New SQL query with a JOIN clause`,explain:`That works but requires writing SQL, which the analyst wants to avoid.`}],answer:`a`},{id:`TF-02`,machineId:T,bulletIds:[`P2.6`],format:`dropdown`,difficulty:2,placement:!0,stem:`In the Reporting warehouse, you need to create a new table that joins the Sales table from the SalesLakehouse lakehouse (same workspace) to the warehouse’s Products table. Complete the T-SQL statement.`,sources:[t.ingestWarehouse,t.queryWarehouse],language:`tsql`,code:`CREATE TABLE Reporting.dbo.SalesByProduct
[[1]]
SELECT p.Category, s.Amount
FROM [[2]] AS s
JOIN Reporting.dbo.Products AS p ON s.ProductID = p.ProductID;`,slots:[{id:`1`,options:[{id:`a`,text:`AS`,explain:`Correct. CREATE TABLE … AS SELECT (CTAS) creates and fills the table from the query.`},{id:`b`,text:`WITH`,explain:`WITH introduces a CTE or table options, not CTAS.`},{id:`c`,text:`INTO`,explain:`INTO belongs to SELECT … INTO, not CREATE TABLE.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`Sales`,explain:`A one-part name resolves in the current warehouse, not in the lakehouse.`},{id:`b`,text:`SalesLakehouse.dbo.Sales`,explain:`Correct. A three-part name (item.schema.table) references the lakehouse table in the same workspace.`},{id:`c`,text:`OPENROWSET(BULK 'SalesLakehouse/Sales')`,explain:`OPENROWSET reads files in Azure storage, not a lakehouse table by name.`}],answer:`b`}]},{id:`TF-03`,machineId:T,bulletIds:[`P2.6`],format:`single`,difficulty:2,trapPairId:`merge-vs-append`,stem:`Sales data is stored in three regional systems with the same columns. You need a single table that contains all sales from all three systems. Which kind of combine operation should the ETL use?`,sources:[t.loadTables],options:[{id:`a`,text:`Merge the tables on SalesOrderID`,explain:`Merging adds columns by matching keys; it doesn’t stack rows from systems with the same structure.`},{id:`b`,text:`Aggregate the tables by region`,explain:`Aggregation summarizes rows; it doesn’t combine the systems’ detail rows.`},{id:`c`,text:`Append the tables (a union)`,explain:`Correct. Learn: data that shares a common structure can be appended; a union of each system’s sales gives the full set.`},{id:`d`,text:`Create a shortcut to each table`,explain:`Shortcuts expose each table separately; they don’t combine them into one.`}],answer:`c`},{id:`TF-04`,machineId:T,bulletIds:[`P2.6`],format:`single`,difficulty:3,placement:!0,stem:`A warehouse in workspace A needs to join to a lakehouse table that lives in workspace B. A three-part-name query fails. You need to query both tables together without copying data. What should you do?`,sources:[t.queryWarehouse,t.endpoint],options:[{id:`a`,text:`Use a four-part name that includes the workspace`,explain:`Cross-database queries reference items in the current workspace; a workspace prefix isn’t the documented fix.`},{id:`b`,text:`Grant the warehouse’s owner the Contributor role in workspace B, then rerun the three-part-name query`,explain:`Roles don’t change the scope of cross-database queries, which is limited to the same workspace.`},{id:`c`,text:`Run COPY INTO from workspace B’s lakehouse`,explain:`COPY INTO copies the data, which the requirement wants to avoid.`},{id:`d`,text:`Create a OneLake shortcut to the table in a lakehouse in workspace A, then join to it`,explain:`Correct. Learn: use OneLake shortcuts to reference tables in other workspaces, then join them in one query.`}],answer:`d`},{id:`TF-05`,machineId:T,bulletIds:[`P2.6`],format:`single`,difficulty:2,placement:!0,stem:`In a Fabric notebook, you have DataFrames df_sale and df_city. You need every sale row matched to its city on CityKey, keeping only matches. Which PySpark expression should you use?`,sources:[t.lakehousePrep,t.notebookCombine],options:[{id:`a`,text:`df_sale.union(df_city)`,explain:`This doesn’t match sales rows to cities on CityKey; Learn’s tutorial uses a join for that.`},{id:`b`,text:`df_sale.join(df_city, df_sale.CityKey == df_city.CityKey, "inner")`,explain:`Correct. Learn’s tutorial joins fact and dimension DataFrames this way with an inner join.`},{id:`c`,text:`df_sale.groupBy("CityKey").sum()`,explain:`groupBy aggregates; it doesn’t bring in the city columns, which takes a join.`},{id:`d`,text:`df_sale.withColumn("City", df_city.City)`,explain:`Learn’s tutorial brings dimension columns in with a join, not withColumn.`}],answer:`b`},{id:`TF-06`,machineId:T,bulletIds:[`P2.6`],format:`yesno`,difficulty:2,stem:`You are planning joins in a Fabric warehouse ETL. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.loadTables,t.queryWarehouse,t.visualQuery],statements:[{id:`s1`,text:`Set-based statements such as CREATE TABLE AS SELECT with joins are likely the most efficient way to load dimensional tables from staging tables in the same workspace.`,answer:!0,explain:`Yes. Learn calls these set-based operations likely the most efficient and fastest way.`},{id:`s2`,text:`Three-part names let a warehouse query join tables from any workspace in the tenant.`,answer:!1,explain:`No. Cross-database queries work within the current workspace.`},{id:`s3`,text:`The visual query editor can run INSERT and UPDATE statements after a merge.`,answer:!1,explain:`No. The visual query editor runs read-only SELECT queries only; DDL and DML aren’t supported.`}]},{id:`TF-07`,machineId:T,bulletIds:[`P2.6`],format:`order`,difficulty:2,stem:`In the warehouse visual query editor, you need to join two tables and keep the result as a reusable view. Put the steps in order.`,sources:[t.visualQuery],items:[{id:`i1`,text:`Select Save as view and confirm the SQL statement`,explain:`Last: Save as view creates the view from the query with load enabled.`},{id:`i2`,text:`Use Merge queries as new and choose the key columns and join kind`,explain:`Second: merge the tables on the common key.`},{id:`i3`,text:`Drag both tables from the Explorer onto the canvas`,explain:`First: tables must be on the canvas before you can merge them.`}],answerOrder:[`i3`,`i2`,`i1`]},{id:`TF-08`,machineId:T,bulletIds:[`P2.5`],format:`single`,difficulty:2,placement:!0,stem:`A warehouse fact table stores one row per sales order line. Reports never need order numbers, and you want a smaller table with one row per date, product, and store. What should the ETL do?`,sources:[t.loadTables],options:[{id:`a`,text:`Create a view that filters out the order number column`,explain:`A view hides the column but leaves the grain and row count unchanged.`},{id:`b`,text:`Partition the fact table by OrderDate`,explain:`Partitioning organizes storage; it doesn’t reduce the grain.`},{id:`c`,text:`Add a nonclustered index on the dimension keys`,explain:`An index wouldn’t change the grain or the row count.`},{id:`d`,text:`Load an aggregated result grouped by all the dimension keys`,explain:`Correct. Learn: aggregation can raise the grain; group by the dimension keys and summarize the measures.`}],answer:`d`},{id:`TF-09`,machineId:T,bulletIds:[`P2.5`],format:`dropdown`,difficulty:2,placement:!0,stem:`In a Fabric warehouse, you need a summary table with total sales and order count per store. Complete the T-SQL.`,sources:[t.ingestWarehouse,t.loadTables],language:`tsql`,code:`CREATE TABLE dbo.StoreSummary AS
SELECT StoreKey, [[1]](Amount) AS TotalSales, COUNT(*) AS Orders
FROM dbo.FactSales
[[2]] StoreKey;`,slots:[{id:`1`,options:[{id:`a`,text:`MAX`,explain:`MAX returns the largest single sale, not the total.`},{id:`b`,text:`SUM`,explain:`Correct. SUM adds the amounts per store.`},{id:`c`,text:`AVG`,explain:`AVG returns the average sale, not the total.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`GROUP BY`,explain:`Correct. GROUP BY StoreKey returns one row per store.`},{id:`b`,text:`ORDER BY`,explain:`ORDER BY sorts; without GROUP BY the aggregates would be invalid alongside StoreKey.`},{id:`c`,text:`PARTITION BY`,explain:`PARTITION BY is used inside OVER() for window functions, not to group a query.`}],answer:`a`}]},{id:`TF-10`,machineId:T,bulletIds:[`P2.5`],format:`single`,difficulty:2,placement:!0,stem:`In a Fabric notebook, you joined sales to dates and cities in a DataFrame named joined. You need total Profit per Date and City. Which PySpark expression should you use?`,sources:[t.lakehousePrep,t.notebookCombine],options:[{id:`a`,text:`joined.groupBy("Date", "City").sum("Profit")`,explain:`Correct. Learn’s tutorial groups by the dimension columns and applies sum to the measures.`},{id:`b`,text:`joined.orderBy("Date", "City").sum("Profit")`,explain:`Totals by Date and City come from groupBy with an aggregation, as in Learn’s tutorial; orderBy only sorts.`},{id:`c`,text:`joined.select("Date", "City", "Profit").distinct()`,explain:`This keeps distinct rows but doesn’t total Profit; totals need groupBy with an aggregation.`},{id:`d`,text:`joined.withColumn("Profit", "sum")`,explain:`withColumn adds a column computed per row; it doesn’t total Profit.`}],answer:`a`},{id:`TF-11`,machineId:T,bulletIds:[`P2.5`],format:`single`,difficulty:2,placement:!0,stem:`You want to build a city-level aggregate table in a lakehouse with Spark SQL in a notebook, replacing the table if it exists. Which statement pattern does Learn’s lakehouse tutorial use?`,sources:[t.lakehousePrep],options:[{id:`a`,text:`COPY INTO … FROM a parquet file`,explain:`COPY INTO is a Fabric warehouse T-SQL statement, not the Spark SQL pattern in a notebook.`},{id:`b`,text:`MERGE INTO … USING … WHEN MATCHED`,explain:`MERGE upserts into an existing table; the tutorial replaces the aggregate table.`},{id:`c`,text:`A temporary view with GROUP BY, then CREATE OR REPLACE TABLE … AS SELECT from it`,explain:`Correct. The tutorial creates a temporary view with GROUP BY and then CREATE OR REPLACE TABLE … AS SELECT from it.`},{id:`d`,text:`SELECT … INTO a new table`,explain:`SELECT INTO is a T-SQL pattern, not the Spark SQL pattern used in the tutorial.`}],answer:`c`},{id:`TF-12`,machineId:T,bulletIds:[`P2.5`],format:`multi`,difficulty:2,stem:`According to Learn’s dimensional modeling guidance, which two outcomes can aggregation achieve when loading a fact table? Choose two.`,sources:[t.loadTables],options:[{id:`a`,text:`Reduce the fact table’s dimensionality`,explain:`Correct. Learn: aggregation can be used to reduce fact table dimensionality.`},{id:`b`,text:`Raise the granularity of the facts`,explain:`Correct. Learn: aggregation can raise the granularity of the facts.`},{id:`c`,text:`Track historical changes to dimension members`,explain:`That’s what slowly changing dimensions do, not aggregation.`},{id:`d`,text:`Enforce foreign key relationships`,explain:`Aggregation doesn’t enforce keys; warehouse FK constraints are NOT ENFORCED anyway.`}],answers:[`a`,`b`]},{id:`TF-13`,machineId:T,bulletIds:[`P2.5`],format:`single`,difficulty:3,stem:`A product manager asks for a sales fact table aggregated to month and product. Later, analysts need to report sales by sales order number. What is the consequence of having aggregated?`,sources:[t.loadTables,t.factTables],options:[{id:`a`,text:`Order-level analysis isn’t possible from that table because the grain was raised`,explain:`Correct. Aggregating removes the order-level detail; the table’s grain no longer supports it.`},{id:`b`,text:`The order numbers become a degenerate dimension automatically`,explain:`Grouping drops the order numbers; nothing converts them into a dimension.`},{id:`c`,text:`Direct Lake reconstructs the order rows on demand`,explain:`Direct Lake reads the table as stored; it can’t restore detail that isn’t there.`},{id:`d`,text:`The SQL analytics endpoint stores the original rows as history`,explain:`The endpoint is a read-only query surface over Delta tables; it doesn’t keep prior detail.`}],answer:`a`},{id:`TF-14`,machineId:T,bulletIds:[`P2.5`],format:`single`,difficulty:1,placement:!0,stem:`You need a low-code way to group rows and aggregate a DataFrame in a Fabric notebook, with the code generated for you. Which Data Wrangler operation should you use?`,sources:[t.dataWrangler],options:[{id:`a`,text:`Multi-label binarizer`,explain:`This splits values into category indicator columns; it doesn’t aggregate.`},{id:`b`,text:`Flash Fill`,explain:`Flash Fill creates a new column from examples; it doesn’t group rows.`},{id:`c`,text:`Scale min/max values`,explain:`Scaling rescales one numeric column; it doesn’t group or aggregate.`},{id:`d`,text:`Group by column and aggregate`,explain:`Correct. Data Wrangler’s Group by column and aggregate operation groups and aggregates, generating code.`}],answer:`d`}],D=`dye-vat`,O=`weave-planner`,k=[{id:`DV-01`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:1,placement:!0,stem:`In a Fabric notebook you load raw sales files into a DataFrame named df. Before you write the Delta table, you need to add a Year column derived from the OrderDate column. Which PySpark call should you use?`,sources:[t.lakehousePrep,t.notebookClean,t.notebookCombine],options:[{id:`a`,text:`df.withColumn("Year", year(col("OrderDate")))`,explain:`Correct. withColumn() adds a new column computed from an expression, as Learn’s lakehouse tutorial does for Year, Quarter, and Month.`},{id:`b`,text:`df.groupBy(year(col("OrderDate")))`,explain:`groupBy() starts an aggregation and changes the grain; it doesn’t add a column to each row.`},{id:`c`,text:`df.withColumnRenamed("OrderDate", "Year")`,explain:`This only renames OrderDate. The values stay full dates and the original column is gone.`},{id:`d`,text:`df.filter(year(col("OrderDate")) > 0)`,explain:`filter() removes rows that fail a condition; it doesn’t add a column.`}],answer:`a`},{id:`DV-02`,machineId:D,bulletIds:[`P2.2`],format:`dropdown`,difficulty:2,placement:!0,stem:`You are loading an employee dimension in a Fabric warehouse from a staging table. The dimension must store a FullName column built from FirstName and LastName. Complete the T-SQL statement.`,sources:[t.ingestWarehouse,t.loadTables,t.concat],language:`tsql`,code:`CREATE TABLE dbo.DimEmployee
[[1]]
SELECT EmployeeID,
       [[2]](FirstName, ' ', LastName) AS FullName,
       HireDate
[[3]] staging.Employee;`,slots:[{id:`1`,options:[{id:`a`,text:`WITH`,explain:`WITH introduces a common table expression or table options, not the query of a CREATE TABLE AS SELECT.`},{id:`b`,text:`AS`,explain:`Correct. CREATE TABLE … AS SELECT (CTAS) creates the table from the query result.`},{id:`c`,text:`INTO`,explain:`INTO belongs to SELECT … INTO, which has a different word order.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`CONCAT`,explain:`Correct. CONCAT joins two or more string values end to end, so the space separates the names.`},{id:`b`,text:`COALESCE`,explain:`COALESCE returns the first non-NULL argument; it doesn’t join strings.`},{id:`c`,text:`TRY_CAST`,explain:`TRY_CAST converts one value to a data type; it takes a single expression.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`USING`,explain:`USING names the source of a MERGE statement, not of a SELECT.`},{id:`b`,text:`INTO`,explain:`INTO names a target table, not the table being read.`},{id:`c`,text:`FROM`,explain:`Correct. FROM names the staging table the SELECT reads.`}],answer:`c`}]},{id:`DV-03`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:2,placement:!0,stem:`A Fabric warehouse stores sales facts up to today and a new budget fact table with monthly targets for the next fiscal year. You are building the date dimension table. Which date range should it cover?`,sources:[t.dimTables],options:[{id:`a`,text:`Only the dates on which at least one sale was recorded`,explain:`Gaps would break date filtering, and budget dates in the future would have no dimension row.`},{id:`b`,text:`The current calendar year, rebuilt every January`,explain:`Rebuilding to one year drops the history the sales facts still reference.`},{id:`c`,text:`Every date used by all fact tables, plus future dates for the budget`,explain:`Correct. Learn: cover the known range used by all fact tables, and include future dates when the warehouse stores targets, budgets, or forecasts.`},{id:`d`,text:`The dates in the sales fact table only; budgets get their own date table`,explain:`One date dimension should serve every fact table so they can be analyzed together.`}],answer:`c`},{id:`DV-04`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:2,placement:!0,stem:`Each January, your team must extend the warehouse date dimension a fixed number of years ahead and refresh fiscal attributes. A pipeline will run the step. According to Learn, how should you implement the extension logic?`,sources:[t.loadTables],options:[{id:`a`,text:`As a DAX calculated table in each semantic model`,explain:`A calculated table lives in one semantic model, so other models and SQL queries wouldn’t see it.`},{id:`b`,text:`As a T-SQL stored procedure in the warehouse`,explain:`Correct. Learn recommends writing the logic to extend or update the date dimension in T-SQL and encapsulating it in a stored procedure.`},{id:`c`,text:`As a OneLake shortcut to a calendar file`,explain:`A shortcut references data in place; it doesn’t generate or extend rows.`},{id:`d`,text:`As a manual upload of a CSV of dates`,explain:`A manual upload can’t run on the pipeline’s schedule and isn’t what Learn recommends.`}],answer:`b`},{id:`DV-05`,machineId:D,bulletIds:[`P2.2`],format:`yesno`,difficulty:2,placement:!0,stem:`You are deciding where to add derived columns in a Fabric solution. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.loadTables,t.ingestWarehouse,t.lakehousePrep],statements:[{id:`s1`,text:`Learn lists computing gross sales revenue (unit price multiplied by quantity) as a calculation that an ETL process can do for a fact table.`,answer:!0,explain:`Yes. Learn’s load-tables article gives gross sales revenue as an example calculation for the sales fact table.`},{id:`s2`,text:`Dataflow Gen2 can only copy columns as they are and can’t produce calculated columns before loading a warehouse.`,answer:!1,explain:`No. Learn: dataflow transformations include changing data types, adding or removing columns, and using functions to produce calculated columns.`},{id:`s3`,text:`Learn’s lakehouse tutorial adds Year and Quarter columns in a notebook and then partitions the Delta table by them.`,answer:!0,explain:`Yes. The tutorial adds Year, Quarter, and Month with withColumn() and writes fact_sale partitioned by Year and Quarter.`}]},{id:`DV-06`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:2,placement:!0,stem:`A notebook adds Year and Quarter columns to a sales DataFrame. You need the Delta table to be written split into folders by the values of those two columns. Which call should you add to the write chain?`,sources:[t.lakehousePrep],options:[{id:`a`,text:`.orderBy("Year", "Quarter")`,explain:`orderBy() sorts rows; it doesn’t split the table into folders by value.`},{id:`b`,text:`.groupBy("Year", "Quarter")`,explain:`groupBy() is a DataFrame aggregation, not a writer option.`},{id:`c`,text:`.mode("append")`,explain:`mode() controls whether the write overwrites or appends; it doesn’t partition.`},{id:`d`,text:`.partitionBy("Year", "Quarter")`,explain:`Correct. Learn’s tutorial writes fact_sale with partitionBy("Year","Quarter").`}],answer:`d`},{id:`DV-07`,machineId:D,bulletIds:[`P2.2`],format:`multi`,difficulty:2,placement:!0,stem:`You need a GrossRevenue column stored in a Fabric warehouse fact table so that every report and SQL query uses the same value. Which two approaches meet the goal? Choose two.`,sources:[t.ingestWarehouse,t.loadTables],options:[{id:`a`,text:`Add a DAX calculated column to one semantic model`,explain:`The column would exist only in that model, not in the warehouse table that SQL queries read.`},{id:`b`,text:`Create a OneLake shortcut to the staging table`,explain:`A shortcut references data where it is; it doesn’t add columns.`},{id:`c`,text:`Compute UnitPrice * Quantity in the SELECT of a CREATE TABLE AS SELECT statement`,explain:`Correct. The column is computed during the load and stored in the warehouse table.`},{id:`d`,text:`Add the calculated column in a Dataflow Gen2 that loads the fact table`,explain:`Correct. Dataflows can use functions to produce calculated columns before ingestion.`}],answers:[`c`,`d`]},{id:`DV-08`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:3,placement:!0,stem:`Analysts need a FullName column for the warehouse Customer table today. The table is reloaded only once a month, and you must not store a second copy of the data. What should you create?`,sources:[t.createView,t.loadTables],options:[{id:`a`,text:`A view that selects the table’s columns plus CONCAT(FirstName, ' ', LastName)`,explain:`Correct. A view is a virtual table defined by a query, so the derived column is available at once without storing data again.`},{id:`b`,text:`A new table loaded with CREATE TABLE AS SELECT that includes the FullName column`,explain:`CTAS stores a second copy of the data, which the requirement forbids.`},{id:`c`,text:`A stored procedure that returns no result set`,explain:`A procedure that returns nothing gives analysts no column to query.`},{id:`d`,text:`A shortcut from a lakehouse to the Customer table`,explain:`A shortcut exposes the same columns; it can’t add a derived column.`}],answer:`a`},{id:`DV-09`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:3,placement:!0,stem:`A teammate prefers Spark SQL to PySpark. In a lakehouse with schemas enabled, you need one statement that reads raw parquet sales files, adds Year and Quarter columns from InvoiceDateKey, and writes a Delta table partitioned by those columns. Which statement should you use?`,sources:[t.lakehousePrep],options:[{id:`a`,text:"CREATE OR REPLACE VIEW sales PARTITIONED BY (Year, Quarter) AS SELECT * FROM parquet.`Files/raw/sales`",explain:`Learn’s tutorial writes a partitioned Delta table, not a view, and this query adds no Year or Quarter column.`},{id:`b`,text:"CREATE OR REPLACE TABLE delta.`Tables/dbo/sales` PARTITIONED BY (Year, Quarter) AS SELECT *, year(InvoiceDateKey) AS Year, quarter(InvoiceDateKey) AS Quarter FROM parquet.`Files/raw/sales`",explain:`Correct. This mirrors the Spark SQL version in Learn’s lakehouse tutorial.`},{id:`c`,text:"INSERT INTO delta.`Tables/dbo/sales` SELECT year(InvoiceDateKey) AS Year, quarter(InvoiceDateKey) AS Quarter, SUM(Quantity) AS Quantity FROM parquet.`Files/raw/sales` GROUP BY year(InvoiceDateKey), quarter(InvoiceDateKey)",explain:`This aggregates the sales to one row per quarter instead of enriching each sale with Year and Quarter.`},{id:`d`,text:"CREATE TABLE sales PARTITIONED BY (InvoiceDateKey) AS SELECT * FROM parquet.`Files/raw/sales`",explain:`This partitions by the raw date and never adds Year or Quarter columns.`}],answer:`b`},{id:`DV-10`,machineId:D,bulletIds:[`P2.2`],format:`single`,difficulty:1,trapPairId:`dataflow-pipeline-notebook`,stem:`A team of business analysts needs to add a calculated column to customer data while ingesting it into a Fabric warehouse. They prefer a code-free experience. What should they use?`,sources:[t.ingestWarehouse],options:[{id:`a`,text:`The COPY INTO statement`,explain:`COPY INTO is a code-rich T-SQL ingestion statement, not a code-free transformation tool.`},{id:`b`,text:`Mirroring`,explain:`Mirroring replicates a source database into OneLake; it doesn’t add calculated columns.`},{id:`c`,text:`A dataflow (Dataflow Gen2)`,explain:`Correct. Learn: dataflows give a code-free experience with transformations such as using functions to produce calculated columns.`},{id:`d`,text:`A OneLake shortcut`,explain:`A shortcut references data in place without transforming it.`}],answer:`c`},{id:`WP-01`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:1,placement:!0,stem:`You are designing DimCustomer in a Fabric warehouse. The source system identifies customers by CustomerID, and the business wants to keep a history of each customer’s region with new rows per change. Which key should the fact table reference?`,sources:[t.dimTables],options:[{id:`a`,text:`The CustomerID natural key from the source system`,explain:`Once history is kept, the same CustomerID appears on several rows, so it can’t identify one version.`},{id:`b`,text:`A composite key of CustomerID and Region`,explain:`Learn recommends a single-column key; a composite key is less efficient and still ambiguous if a region repeats.`},{id:`c`,text:`A warehouse-generated integer surrogate key`,explain:`Correct. Learn: a surrogate key is required for SCD type 2 because natural keys repeat across versions.`},{id:`d`,text:`The customer’s email address`,explain:`An email is a changing attribute, not a stable, meaningless key.`}],answer:`c`},{id:`WP-02`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`scd1-vs-scd2`,stem:`A salesperson moves from the Australia region to the United Kingdom region. Reports must keep showing past sales under Australia and new sales under the United Kingdom. How should the warehouse ETL handle the change in the salesperson dimension?`,sources:[t.dimTables],options:[{id:`a`,text:`Apply an SCD type 1 change that overwrites the region`,explain:`Type 1 overwrites the row, so all past sales would roll up to the United Kingdom as if the move always applied.`},{id:`b`,text:`Apply an SCD type 2 change that adds a new version row`,explain:`Correct. Type 2 expires the current version and inserts a new one, so old facts keep the Australia version.`},{id:`c`,text:`Apply an SCD type 3 change with a PreviousRegion column`,explain:`Type 3 tracks limited history in columns and is hard to use in a semantic model. Learn suggests considering type 2.`},{id:`d`,text:`Mark the existing row with IsDeleted = 1`,explain:`A soft delete records a deletion in the source, not an attribute change.`}],answer:`b`},{id:`WP-03`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:1,placement:!0,trapPairId:`scd1-vs-scd2`,stem:`A customer’s email address was entered with a typo, and the source system has corrected it. Nobody needs to analyze the old value. How should the warehouse ETL apply the change to the customer dimension?`,sources:[t.dimTables],options:[{id:`a`,text:`Overwrite the attribute with an SCD type 1 change`,explain:`Correct. Learn: type 1 overwrites the row, can be used to correct errors, and suits most attributes like name and email.`},{id:`b`,text:`Insert a new version with an SCD type 2 change`,explain:`Type 2 keeps history that nobody needs and adds a version row for a typo.`},{id:`c`,text:`Truncate and fully reload the customer dimension`,explain:`Learn says never truncate and reload a dimension with generated surrogate keys; it invalidates fact references.`},{id:`d`,text:`Soft delete the existing row and insert a new customer member`,explain:`That would split one customer into two members and orphan existing facts.`}],answer:`a`},{id:`WP-04`,machineId:O,bulletIds:[`P2.3`],format:`match`,difficulty:2,placement:!0,stem:`You are designing fact tables in a Fabric warehouse. Match each requirement to the fact table type Learn recommends.`,sources:[t.factTables],prompts:[{id:`p1`,text:`Store every sales order line as it happens`},{id:`p2`,text:`Store the end-of-day stock balance of every product`},{id:`p3`,text:`Track each order through ordered, shipped, and delivered dates, updating the row at each milestone`}],choices:[{id:`c1`,text:`Transaction fact table`},{id:`c2`,text:`Periodic snapshot fact table`},{id:`c3`,text:`Accumulating snapshot fact table`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`A transaction fact table stores business events at the lowest grain; Learn’s example is a sales fact storing every order line.`},{promptId:`p2`,choiceId:`c2`,explain:`A periodic snapshot stores measurements at set intervals; Learn’s example is a daily end-of-day inventory balance.`},{promptId:`p3`,choiceId:`c3`,explain:`An accumulating snapshot records milestones of a process, with several date keys, and the row is updated as each milestone occurs.`}]},{id:`WP-05`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,placement:!0,stem:`A product was deleted in the source system. The warehouse product dimension has generated surrogate keys, and existing fact rows reference the product. What should the ETL process do?`,sources:[t.loadTables],options:[{id:`a`,text:`Delete the product row from the dimension table`,explain:`Deleting the row would leave fact rows pointing at a key that no longer exists.`},{id:`b`,text:`Truncate the dimension and reload it from the source`,explain:`Learn says never truncate and reload a dimension with generated surrogate keys; it invalidates the facts.`},{id:`c`,text:`Set the product’s surrogate key to NULL`,explain:`The key must stay valid so fact rows still join to the member.`},{id:`d`,text:`Set an IsDeleted bit column to 1 for the product`,explain:`Correct. Learn: record source deletions as soft deletes with a bit column such as IsDeleted, and filter them out in reports.`}],answer:`d`},{id:`WP-06`,machineId:O,bulletIds:[`P2.3`],format:`dropdown`,difficulty:3,placement:!0,trapPairId:`scd1-vs-scd2`,stem:`You need to apply SCD type 1 changes to the Email attribute of a warehouse customer dimension and add customers that are new in staging. Complete the T-SQL statement.`,sources:[t.merge,t.tsqlSurface,t.loadTables],language:`tsql`,code:`MERGE dbo.DimCustomer AS tgt
USING staging.Customer AS src
ON tgt.[[1]] = src.CustomerID
WHEN [[2]] THEN UPDATE SET tgt.Email = src.Email
WHEN NOT MATCHED BY [[3]] THEN
  INSERT (CustomerID, Email) VALUES (src.CustomerID, src.Email);`,slots:[{id:`1`,options:[{id:`a`,text:`Customer_SK`,explain:`The staging data comes from the source system and has no warehouse surrogate key to match on.`},{id:`b`,text:`CustomerID`,explain:`Correct. ETL matches incoming rows to members on the natural (business) key.`},{id:`c`,text:`Email`,explain:`Email is the attribute being changed, so it can’t identify the member.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`MATCHED`,explain:`Correct. Rows that exist in both get the type 1 overwrite.`},{id:`b`,text:`NOT MATCHED`,explain:`NOT MATCHED rows don’t exist in the target, so there’s nothing to update.`},{id:`c`,text:`NOT MATCHED BY SOURCE`,explain:`This targets dimension rows missing from staging, not changed rows.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`SOURCE`,explain:`NOT MATCHED BY SOURCE finds target rows missing from the source; you can’t INSERT for those.`},{id:`b`,text:`KEY`,explain:`KEY isn’t a MERGE keyword.`},{id:`c`,text:`TARGET`,explain:`Correct. NOT MATCHED BY TARGET finds source rows the dimension doesn’t have yet, which are inserted.`}],answer:`c`}]},{id:`WP-07`,machineId:O,bulletIds:[`P2.3`],format:`yesno`,difficulty:2,placement:!0,stem:`You are reviewing a design for a star schema in a Fabric warehouse. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.tsqlSurface,t.loadTables],statements:[{id:`s1`,text:`A PRIMARY KEY constraint can be added to a warehouse table only if NOT ENFORCED is specified.`,answer:!0,explain:`Yes. Learn: PRIMARY KEY, UNIQUE, and FOREIGN KEY constraints are supported only with NOT ENFORCED.`},{id:`s2`,text:`Whenever possible, a fact table should be loaded incrementally rather than truncated and reloaded.`,answer:!0,explain:`Yes. Learn calls incremental loads more scalable; truncating and reloading a large fact table is a last resort.`},{id:`s3`,text:`Truncating and fully reloading a dimension with generated surrogate keys is the recommended way to apply source changes.`,answer:!1,explain:`No. Learn says you should never do this, because it invalidates fact references and can lose SCD type 2 history.`}]},{id:`WP-08`,machineId:O,bulletIds:[`P2.3`],format:`order`,difficulty:2,placement:!0,stem:`A pipeline runs the nightly ETL for a Fabric warehouse star schema. Put the steps in the order Learn recommends.`,sources:[t.loadTables],items:[{id:`i3`,text:`Process the dimension tables, applying SCD changes`,explain:`Third. Dimensions are processed before facts so every new member exists.`},{id:`i1`,text:`Truncate the staging tables`,explain:`First. Learn: staging table contents should be removed at the start of the ETL process.`},{id:`i4`,text:`Load the fact table, looking up the surrogate key for each dimension`,explain:`Last. Each fact row needs the current surrogate key of members that now exist.`},{id:`i2`,text:`Load the staging tables with source data`,explain:`Second. Source data is staged before it is transformed into the dimensional model.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`WP-09`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,stem:`A periodic snapshot fact table in a Fabric warehouse is loaded every night with the AgeInDays of every inventory item on each shelf. How should AgeInDays be aggregated?`,sources:[t.factTables],options:[{id:`a`,text:`Summed across the items on a shelf for one night, but not summed across nights`,explain:`Correct. Periodic snapshot measures are semi-additive: they can’t be summed across time periods. Learn’s own example: don’t sum an item’s age sampled nightly, but you could sum the age of all items on a shelf each night.`},{id:`b`,text:`Summed across every dimension, including dates`,explain:`A measure in a periodic snapshot can’t be summed across other time periods.`},{id:`c`,text:`Never summed across any dimension`,explain:`That describes a non-additive measure, such as a temperature reading. Item ages on a shelf can be summed for one night.`},{id:`d`,text:`Summed only across nights, never across items in the same snapshot`,explain:`This reverses the rule: time is the dimension a snapshot measure can’t be summed across.`}],answer:`a`},{id:`WP-10`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:3,placement:!0,stem:`Orders in a SQL Server source aren’t numbered in sequence and have no reliable timestamp column. You need an incremental load of the warehouse fact table that detects new and changed rows efficiently. What should you do?`,sources:[t.loadTables],options:[{id:`a`,text:`Store the highest order number loaded and read orders above it next time`,explain:`A high watermark only works when the source records orders in a reliable sequence.`},{id:`b`,text:`Truncate and reload the fact table every night`,explain:`Learn calls truncate-and-reload of a large fact table a last resort.`},{id:`c`,text:`Enable change data capture or change tracking on the source tables`,explain:`Correct. Learn: when source data can’t identify new facts, SQL Server features like CDC or change tracking can detect changed rows.`},{id:`d`,text:`Compare every fact row to the source by order and line number`,explain:`Learn warns that correlating by attributes can be very expensive for large fact tables.`}],answer:`c`},{id:`WP-11`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`endpoint-vs-warehouse`,stem:`You must build a star schema in a Fabric lakehouse, with a fact_sale table and several dimension tables loaded from raw parquet files. How should you create the tables?`,sources:[t.lakehousePrep,t.endpoint],options:[{id:`a`,text:`Run CREATE TABLE and INSERT statements in the lakehouse SQL analytics endpoint`,explain:`The SQL analytics endpoint is read-only over Delta tables; you can’t insert data through it.`},{id:`b`,text:`Write each DataFrame as a Delta table under Tables from a notebook`,explain:`Correct. Learn’s tutorial writes fact_sale and the dimension_* tables as Delta tables from notebooks.`},{id:`c`,text:`Save each table as a CSV file in the Files section`,explain:`Files holds unmanaged files; the star schema tables belong in Tables as Delta tables.`},{id:`d`,text:`Define each table as a DAX calculated table in a model`,explain:`That builds tables in one semantic model, not in the lakehouse.`}],answer:`b`},{id:`WP-12`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:3,placement:!0,stem:`A sales fact row arrives for a customer whose details haven’t reached the warehouse yet. Only the customer’s natural key is known. The details will arrive in a later load. According to Learn, what should the fact load do?`,sources:[t.loadTables,t.factTables],options:[{id:`a`,text:`Keep the fact row in staging until the customer arrives`,explain:`Learn says the fact row must still be inserted, not held back.`},{id:`b`,text:`Insert the fact row with a NULL customer key`,explain:`A valid dimension key must still be stored; Learn recommends NOT NULL dimension keys.`},{id:`c`,text:`Create a customer member with Unknown attributes and IsInferredMember set to TRUE`,explain:`Correct. The inferred member gets a real surrogate key now, and the dimension load updates it when the details arrive.`},{id:`d`,text:`Truncate and reload the customer dimension so the new customer is included before the facts`,explain:`Reloading wouldn’t add a customer the source hasn’t sent, and it would break existing fact references.`}],answer:`c`},{id:`WP-13`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:1,stem:`You are creating the surrogate key of the date dimension in a Fabric warehouse. Which format does Learn recommend?`,sources:[t.dimTables],options:[{id:`a`,text:`A GUID generated when each row is inserted`,explain:`A GUID is wide and meaningless; the date key is the exception that should be readable.`},{id:`b`,text:`The date stored as an int in YYYYMMDD format`,explain:`Correct. Learn: the date surrogate key should store YYYYMMDD as int, which is efficient, sorted, and ISO 8601 compliant.`},{id:`c`,text:`An IDENTITY integer that starts at 1`,explain:`An arbitrary sequence works for most dimensions, but Learn makes date and time keys the readable exception.`},{id:`d`,text:`The date stored as text in DD/MM/YYYY format`,explain:`Text is larger and doesn’t sort in date order; Learn uses int YYYYMMDD.`}],answer:`b`},{id:`WP-14`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,stem:`A warehouse sales fact table has OrderDate_Date_FK and ShipDate_Date_FK columns. Both reference the same physical date dimension. What is this design called?`,sources:[t.factTables],options:[{id:`a`,text:`A junk dimension`,explain:`A junk dimension combines many small lookup attributes into one table.`},{id:`b`,text:`A snowflake dimension`,explain:`A snowflake normalizes one dimension across several related tables.`},{id:`c`,text:`A degenerate dimension`,explain:`A degenerate dimension is formed from a fact table attribute, such as an order number.`},{id:`d`,text:`A role-playing dimension`,explain:`Correct. Learn: a fact table that references one dimension several times, each in a distinct role, uses a role-playing dimension.`}],answer:`d`},{id:`WP-15`,machineId:O,bulletIds:[`P2.3`],format:`single`,difficulty:2,placement:!0,stem:`Analysts built a dimensional model in Power Query inside a semantic model. They now need to analyze past sales by each customer’s region at the time of sale, and regions change. What does Learn recommend?`,sources:[t.dimOverview,t.dimTables],options:[{id:`a`,text:`Configure incremental refresh on the semantic model`,explain:`Incremental refresh controls which partitions are refreshed; it doesn’t store versions of changed dimension attributes.`},{id:`b`,text:`Add a DAX calculated column that stores the current region`,explain:`A calculated column is recomputed from current data, so it can’t recall a past region.`},{id:`c`,text:`Load the customers with a Dataflow Gen2 that overwrites changed customer rows`,explain:`Overwriting is an SCD type 1 pattern, which loses the history that’s needed.`},{id:`d`,text:`Create a data warehouse with periodic ETL that stores dimension changes`,explain:`Correct. Learn: Power Query can’t manage historical change, so use a warehouse whose ETL captures and stores dimension changes.`}],answer:`d`},{id:`WP-16`,machineId:O,bulletIds:[`P2.4`],format:`single`,difficulty:2,placement:!0,trapPairId:`star-vs-snowflake`,stem:`A Fabric warehouse stores products in three related tables: Product, Subcategory, and Category. A semantic model needs a Category > Subcategory > Product hierarchy. What should you provide to the model?`,sources:[t.dimTables],options:[{id:`a`,text:`A view that joins the three tables into one denormalized product result`,explain:`Correct. Learn: a model hierarchy can only use columns from one table, so a snowflake should be exposed through a joining view.`},{id:`b`,text:`All three tables, related in the model, with one hierarchy spanning all of them`,explain:`A hierarchy can only be based on columns from a single model table.`},{id:`c`,text:`A OneLake shortcut to each of the three tables`,explain:`Shortcuts still deliver three separate tables, so the hierarchy problem remains.`},{id:`d`,text:`An SCD type 2 version of the Category table`,explain:`SCD type 2 tracks history; it doesn’t combine the hierarchy levels into one table.`}],answer:`a`},{id:`WP-17`,machineId:O,bulletIds:[`P2.4`],format:`dropdown`,difficulty:2,placement:!0,trapPairId:`star-vs-snowflake`,stem:`You need to flatten a snowflaked product dimension in a Fabric warehouse so that each product row carries its subcategory and category names. Complete the T-SQL statement.`,sources:[t.createView,t.dimTables,t.unionOp,t.exceptIntersect],language:`tsql`,code:`[[1]] dbo.vDimProduct
AS
SELECT p.Product_SK, p.ProductName, s.SubcategoryName, c.CategoryName
FROM dbo.Product AS p
[[2]] dbo.Subcategory AS s ON p.Subcategory_FK = s.Subcategory_SK
JOIN dbo.Category AS c ON s.[[3]] = c.Category_SK;`,slots:[{id:`1`,options:[{id:`a`,text:`CREATE PROCEDURE`,explain:`A procedure runs statements when executed; consumers can’t select from it like a table.`},{id:`b`,text:`CREATE VIEW`,explain:`Correct. A view stores the joining query so consumers see one denormalized product table.`},{id:`c`,text:`CREATE SCHEMA`,explain:`A schema is a container for objects, not a query.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`JOIN`,explain:`Correct. An inner join adds the subcategory columns to each product.`},{id:`b`,text:`UNION`,explain:`UNION stacks rows from two queries; it doesn’t add columns.`},{id:`c`,text:`EXCEPT`,explain:`EXCEPT returns rows from one query that aren’t in another.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`Subcategory_SK`,explain:`That is the subcategory’s own key, already used in the previous join.`},{id:`b`,text:`Product_SK`,explain:`Product keys don’t relate subcategories to categories.`},{id:`c`,text:`Category_FK`,explain:`Correct. The subcategory’s foreign key references the category’s surrogate key.`}],answer:`c`}]},{id:`WP-18`,machineId:O,bulletIds:[`P2.4`],format:`single`,difficulty:1,trapPairId:`star-vs-snowflake`,stem:`Every row of a warehouse product dimension repeats its subcategory name and category name, so the same category name appears on many rows. Which term describes this design?`,sources:[t.dimTables],options:[{id:`a`,text:`Normalization`,explain:`Normalization reduces repeated data, which is the opposite of this design.`},{id:`b`,text:`A snowflake dimension`,explain:`A snowflake splits the hierarchy into separate related tables.`},{id:`c`,text:`Denormalization`,explain:`Correct. Learn: denormalization stores precomputed redundant data, typically by flattening hierarchies.`},{id:`d`,text:`SCD type 3`,explain:`SCD type 3 tracks limited history in extra columns.`}],answer:`c`},{id:`WP-19`,machineId:O,bulletIds:[`P2.4`],format:`single`,difficulty:2,stem:`A warehouse sales fact relates to six tiny dimensions, each holding a few values: payment type, order channel, promotion flag, gift-wrap flag, rush flag, and return flag. You want to simplify the model. What should you create?`,sources:[t.dimTables],options:[{id:`a`,text:`A role-playing dimension`,explain:`Role-playing describes one dimension referenced several times by a fact table.`},{id:`b`,text:`A junk dimension`,explain:`Correct. Learn: when you have many small dimensions, consider consolidating them into a junk dimension.`},{id:`c`,text:`A snowflake dimension`,explain:`A snowflake normalizes one dimension into more tables, which adds tables rather than removing them.`},{id:`d`,text:`A periodic snapshot table`,explain:`A periodic snapshot is a fact table type, not a way to combine dimensions.`}],answer:`b`},{id:`WP-20`,machineId:O,bulletIds:[`P2.4`],format:`yesno`,difficulty:2,placement:!0,trapPairId:`star-vs-snowflake`,stem:`You are designing dimensions for a Fabric warehouse that will feed Power BI semantic models. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.dimTables],statements:[{id:`s1`,text:`Learn says dimension tables should almost always be denormalized.`,answer:!0,explain:`Yes. Learn: it’s almost always the case that dimension tables should be denormalized.`},{id:`s2`,text:`A hierarchy in a semantic model can combine columns from several related tables.`,answer:!1,explain:`No. A hierarchy can only be based on columns from a single semantic model table.`},{id:`s3`,text:`A denormalized product dimension contains redundant data, such as category names repeated on many rows.`,answer:!0,explain:`Yes. Redundant data comes from flattening hierarchies into the dimension.`}]},{id:`WP-21`,machineId:O,bulletIds:[`P2.4`],format:`multi`,difficulty:2,placement:!0,stem:`Customer data in a Fabric warehouse is normalized into Customer, City, and Country tables. You need consumers to see one denormalized customer table. Which two approaches meet the goal? Choose two.`,sources:[t.dimTables,t.loadTables,t.createView],options:[{id:`a`,text:`Load a new table with CREATE TABLE AS SELECT that joins the three tables`,explain:`Correct. Joining in the ETL stores one flattened customer table.`},{id:`b`,text:`Add NOT ENFORCED foreign key constraints between the tables`,explain:`Constraints describe relationships; they don’t combine the tables into one.`},{id:`c`,text:`Create a view that joins the three tables`,explain:`Correct. A view delivers a denormalized result over the normalized tables.`},{id:`d`,text:`Split Country into a separate Region table`,explain:`This normalizes further, adding another table instead of flattening.`}],answers:[`a`,`c`]}],A=[...C,...a,...E,...k,...x,...v,...h,...i];export{t as n,A as t};